--
-- Name: create_culture_a2e(text, text, text, text, text, text, date, integer, text, text, text[], integer, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_culture_a2e(p_kind text, p_mode text, p_title text, p_country text, p_region text, p_city text, p_start date, p_days integer, p_layer text, p_vibe text, p_types text[], p_prep integer, p_finale text, p_place text, p_repeat boolean DEFAULT false) RETURNS uuid
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$ SELECT trip_private.create_culture_a2e(p_kind,p_mode,p_title,p_country,p_region,p_city,p_start,p_days,p_layer,p_vibe,p_types,p_prep,p_finale,p_place,p_repeat) $$;


--
-- Name: create_culture_play_mode(text, text, text, text, text, text, date, integer, text, text, text[], text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_culture_play_mode(p_kind text, p_mode text, p_title text, p_country text, p_region text, p_city text, p_start date, p_days integer, p_layer text, p_vibe text, p_types text[], p_finale text, p_place text, p_repeat boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_exp uuid; v_trip uuid;
BEGIN
  IF p_kind NOT IN ('explore','show') OR p_mode NOT IN ('solo','online','offline') OR (p_kind='explore' AND p_mode='solo') THEN RAISE EXCEPTION 'Choose who is playing'; END IF;
  v_exp := trip_private.create_culture_a2e(p_kind, CASE WHEN p_mode='solo' THEN 'solo' ELSE 'group' END, p_title, p_country, p_region, p_city, p_start, p_days, p_layer, p_vibe, p_types, 0, p_finale, p_place, p_repeat);
  IF p_mode<>'solo' THEN
    SELECT trip_id INTO v_trip FROM public.culture_experiences WHERE id=v_exp AND creator_id=auth.uid() AND a2e_kind=p_kind;
    IF v_trip IS NULL THEN RAISE EXCEPTION 'Could not create your room'; END IF;
    UPDATE public.trips SET play_arrangement=p_mode, join_code_enabled=(p_mode='online') WHERE id=v_trip AND season_rule='a2c' AND a2e_room=true AND is_sandbox=false;
  END IF;
  RETURN v_exp;
END $$;


