--
-- Name: culture_exp_days; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.culture_exp_days (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    experience_id uuid NOT NULL,
    day_number integer NOT NULL,
    title text NOT NULL,
    what_to_do text NOT NULL,
    backstory text DEFAULT ''::text NOT NULL,
    keywords text[] DEFAULT '{}'::text[] NOT NULL,
    points integer DEFAULT 10 NOT NULL,
    source text DEFAULT 'manual'::text NOT NULL,
    done_at timestamp with time zone,
    note text,
    photos text[] DEFAULT '{}'::text[] NOT NULL,
    with_users uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    review_stars integer,
    review_text text,
    place text,
    fact text,
    ref_url text,
    confirmed_by uuid,
    confirmed_at timestamp with time zone,
    CONSTRAINT culture_exp_days_backstory_check CHECK ((char_length(backstory) <= 600)),
    CONSTRAINT culture_exp_days_day_number_check CHECK (((day_number >= 1) AND (day_number <= 3650))),
    CONSTRAINT culture_exp_days_fact_check CHECK (((fact IS NULL) OR (char_length(fact) <= 200))),
    CONSTRAINT culture_exp_days_note_check CHECK (((note IS NULL) OR (char_length(note) <= 500))),
    CONSTRAINT culture_exp_days_place_check CHECK (((place IS NULL) OR (char_length(place) <= 120))),
    CONSTRAINT culture_exp_days_points_check CHECK (((points >= 0) AND (points <= 50))),
    CONSTRAINT culture_exp_days_ref_url_check CHECK (((ref_url IS NULL) OR ((char_length(ref_url) <= 500) AND (ref_url ~ '^https://'::text)))),
    CONSTRAINT culture_exp_days_review_stars_check CHECK (((review_stars IS NULL) OR ((review_stars >= 1) AND (review_stars <= 5)))),
    CONSTRAINT culture_exp_days_review_text_check CHECK (((review_text IS NULL) OR (char_length(review_text) <= 240))),
    CONSTRAINT culture_exp_days_source_check CHECK ((source = ANY (ARRAY['pool'::text, 'ai'::text, 'manual'::text]))),
    CONSTRAINT culture_exp_days_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 120))),
    CONSTRAINT culture_exp_days_what_to_do_check CHECK ((char_length(what_to_do) <= 600))
);


