--
-- Name: season_points(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.season_points(p_trip uuid, p_season text) RETURNS TABLE(user_id uuid, games integer, quests integer, showcase integer, legacy integer, other integer, total integer)
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
 SELECT s.user_id,s.games,s.quests,s.showcase,s.legacy,s.other, greatest(0, s.games+s.quests+s.showcase+s.legacy+s.other)
 FROM trip_private.season_points(p_trip,p_season) s ORDER BY 7 DESC, 1 $$;


