--
-- Name: a2c_minor_trip(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2c_minor_trip(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT coalesce((SELECT t.season_rule='a2c' AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=t.id AND m.status='approved' AND trip_private.age_of(m.user_id) BETWEEN 0 AND 17) FROM public.trips t WHERE t.id=p_trip),false) $$;


--
-- Name: a2c_quest_card(uuid, uuid, text, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2c_quest_card(p_trip uuid, p_user uuid, p_kind text, p_drop integer, p_dest text) RETURNS TABLE(title text, mission_text text, backstory text, keywords text[], presentation_tag text, insight text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 WITH available AS (
 SELECT sm.*,replace(sm.title,'{destination}',p_dest) AS filled_title,replace(sm.text,'{destination}',p_dest) AS filled_text,
 -- New rooms (play_arrangement set) count uses across every slot/tag and solo guide; legacy a2c keeps per-tag counting
 (SELECT count(*) FROM public.sealed_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (t.play_arrangement IS NOT NULL OR x.presentation_tag=sm.presentation_tag) AND lower(btrim(x.title)) LIKE lower(btrim(replace(sm.title,'{destination}',p_dest)))||'%' )
  + CASE WHEN t.play_arrangement IS NOT NULL THEN (SELECT count(*) FROM public.solo_quests sq WHERE sq.user_id=p_user AND sq.experience_id=t.solo_experience_id AND lower(btrim(sq.title)) LIKE lower(btrim(replace(sm.title,'{destination}',p_dest)))||'%') ELSE 0 END AS prior_uses,
 (SELECT max(x.created_at) FROM public.sealed_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (t.play_arrangement IS NOT NULL OR x.presentation_tag=sm.presentation_tag) AND lower(btrim(x.title)) LIKE lower(btrim(replace(sm.title,'{destination}',p_dest)))||'%') AS last_used,
 -- Just me: prefer one-person tasks; squad-worded tasks only as a last resort (never an empty draw)
 CASE WHEN t.play_arrangement='solo' AND (coalesce(sm.text,'')||' '||coalesce(sm.title,'')) ~* '\m(squad|team|teams|everyone|group|each player|together|crew)\M' THEN 1 ELSE 0 END AS mode_penalty
 FROM public.security_missions sm JOIN public.trips t ON t.id=p_trip
 WHERE t.season_rule='a2c' AND sm.trip_id IS NULL AND sm.kind=CASE WHEN p_kind='sealed' THEN 'checkin' ELSE 'home' END
 AND sm.presentation_tag=CASE WHEN p_kind='sealed' THEN 'video_call' WHEN t.kind='at_home' THEN 'at_home_finale' ELSE 'trip_meetup' END
 AND length(btrim(sm.insight))>12 AND sm.budget_note IS NOT NULL
 AND (sm.category NOT ILIKE '%adult%' OR (t.vibe='Party' AND NOT t.has_minors AND NOT trip_private.a2c_minor_trip(p_trip) AND trip_private.age_of(p_user)>=21))
 AND NOT ((t.has_minors OR trip_private.a2c_minor_trip(p_trip)) AND (coalesce(sm.text,'')||' '||coalesce(sm.title,'')) ~* '(stranger|passer|(photo|photograph|film|record|video|selfie)\w*\s+(with\s+|of\s+)?(a\s+|an\s+|the\s+)?(local|people|person|someone|vendor|crowd))')
 AND NOT EXISTS (SELECT 1 FROM public.season_quests x WHERE x.trip_id=p_trip AND x.user_id=p_user AND (lower(btrim(x.title))=lower(btrim(replace(sm.title,'{destination}',p_dest))) OR lower(btrim(x.mission_text))=lower(btrim(replace(sm.text,'{destination}',p_dest)))))
 ), chosen AS (
 SELECT a.* FROM available a ORDER BY a.prior_uses ASC, a.mode_penalty ASC, a.last_used ASC NULLS FIRST, md5(a.id::text||p_trip::text||p_user::text||p_drop::text) LIMIT 1
 )
 SELECT CASE WHEN c.prior_uses=0 THEN c.filled_title ELSE c.filled_title||' · new angle '||(c.prior_uses+1)::text END,
 CASE WHEN c.prior_uses=0 THEN c.filled_text ELSE c.filled_text||' This time, choose a different verified example, compare it with the last one and tell the squad what changed. Flight remix '||(c.prior_uses+1)::text||'.' END,
 replace(c.backstory,'{destination}',p_dest),ARRAY(SELECT replace(k,'{destination}',p_dest) FROM unnest(c.keywords) k),c.presentation_tag,replace(c.insight,'{destination}',p_dest)
 FROM chosen c $$;


--
-- Name: a2c_quest_insights(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2c_quest_insights(p_trip uuid) RETURNS TABLE(quest_id uuid, insight text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT q.id,q.insight FROM public.sealed_quests q JOIN public.trips t ON t.id=q.trip_id WHERE t.season_rule='a2c' AND q.trip_id=p_trip AND q.user_id=auth.uid() AND trip_private.is_trip_member(p_trip,auth.uid()) AND q.insight IS NOT NULL AND (q.kind='showcase' OR (q.opened_at IS NOT NULL AND now()<least(q.opened_at+interval '24 hours',trip_private.quest_cutoff(p_trip)))) $$;


--
-- Name: a2e_culture_access(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2e_culture_access(p_exp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS(SELECT 1 FROM public.culture_experiences e WHERE e.id=p_exp AND e.a2e_kind IS NOT NULL AND (e.creator_id=auth.uid() OR (e.play_mode='group' AND e.trip_id IS NOT NULL AND trip_private.is_trip_member(e.trip_id,auth.uid())))) $$;


--
-- Name: a2e_group_join_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2e_group_join_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.trip_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.trips t WHERE t.id=NEW.trip_id AND t.a2e_room AND t.vibe='party') AND coalesce(trip_private.age_of(NEW.user_id),0)<21 THEN RAISE EXCEPTION 'This Party room is for 21+ only'; END IF; RETURN NEW; END $$;


--
-- Name: a2e_night_theme(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2e_night_theme(p_trip uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT CASE e.culture_layer WHEN 'food' THEN ARRAY['Taste It','Make It','Guess It','Know It'] WHEN 'music' THEN ARRAY['Sing It','Move It','Guess It'] WHEN 'language' THEN ARRAY['Know It','Guess It','Tell It'] WHEN 'traditions' THEN ARRAY['Know It','Make It','Tell It','Dress It'] WHEN 'history' THEN ARRAY['Know It','Tell It','Draw It'] WHEN 'fashion' THEN ARRAY['Draw It','Make It','Dress It'] WHEN 'games' THEN ARRAY['Act It','Team Up','Vote It','Know It'] WHEN 'everyday' THEN ARRAY['Know Each Other','Tell It','Guess It','Find It'] ELSE ARRAY['Taste It','Sing It','Know It','Make It','Move It','Tell It','Draw It','Guess It'] END FROM public.culture_experiences e WHERE e.trip_id=p_trip AND e.a2e_kind IN ('show','explore') AND e.play_mode='group' AND trip_private.is_trip_member(p_trip,auth.uid()) LIMIT 1 $$;


--
-- Name: a2e_showcase_code(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2e_showcase_code() RETURNS text
    LANGUAGE sql
    SET search_path TO 'public', 'extensions'
    AS $$ SELECT upper(substr(translate(encode(extensions.gen_random_bytes(12),'hex'),'01','AB'),1,16)) $$;


--
-- Name: a2e_solo_ensure(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.a2e_solo_ensure(p_exp uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; d int; v_today date; v_first int; c public.security_missions; v_dest text; v_age int; v_layer text; v_title text; v_text text;
BEGIN
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp;
 IF NOT FOUND OR e.a2e_kind IS NULL OR e.play_mode<>'solo' OR e.creator_id IS DISTINCT FROM auth.uid() THEN RETURN; END IF;
 v_today:=trip_private.solo_today(auth.uid()); v_first:=CASE WHEN e.a2e_kind='inspire' THEN 1-coalesce(e.prep_days,0) ELSE 1 END;
 v_dest:=coalesce(nullif(e.city,''),nullif(e.region,''),e.country); v_age:=coalesce(trip_private.age_of(auth.uid()),0);
 FOR d IN v_first..least(e.days,v_today-e.start_date+1) LOOP
  IF EXISTS(SELECT 1 FROM public.solo_quests q WHERE q.experience_id=p_exp AND q.day_number=d) THEN CONTINUE; END IF;
  v_layer:=CASE WHEN e.culture_layer='food' THEN 'food' WHEN e.culture_layer='music' THEN 'music' WHEN e.culture_layer='language' THEN 'language' WHEN e.culture_layer='traditions' THEN 'traditions' WHEN e.culture_layer='history' THEN 'history' WHEN e.culture_layer='fashion' THEN 'art' WHEN e.culture_layer='games' THEN 'sports' WHEN e.culture_layer='everyday' THEN 'work' END;
  SELECT * INTO c FROM public.security_missions sm WHERE sm.trip_id IS NULL AND sm.kind='solo' AND sm.presentation_tag='solo_guide' AND length(btrim(sm.insight))>12
   AND (v_layer IS NULL OR sm.category=v_layer)
   AND (v_age>=21 OR NOT (sm.traveler_tags @> ARRAY['night_owl']))
   AND NOT (v_age<18 AND (sm.text||' '||sm.title) ~* '(stranger|passer|after dark|late at night|photograph.*(local|person|people))')
   AND NOT EXISTS (SELECT 1 FROM public.solo_quests q JOIN public.culture_experiences x ON x.id=q.experience_id WHERE q.user_id=auth.uid() AND x.country=e.country AND x.culture_layer IS NOT DISTINCT FROM e.culture_layer AND lower(q.title)=lower(replace(sm.title,'{destination}',v_dest)))
   ORDER BY (sm.traveler_tags && e.traveler_types) DESC,md5(sm.id::text||p_exp::text||d::text) LIMIT 1;
  IF NOT FOUND THEN
   SELECT * INTO c FROM public.security_missions sm WHERE sm.trip_id IS NULL AND sm.kind='solo' AND sm.presentation_tag='solo_guide' AND (v_age>=21 OR NOT (sm.traveler_tags @> ARRAY['night_owl'])) AND (v_layer IS NULL OR sm.category=v_layer)
   AND length(btrim(sm.insight))>12 AND NOT (v_age<18 AND (sm.text||' '||sm.title) ~* '(stranger|passer|after dark|late at night|photograph.*(local|person|people))') ORDER BY md5(sm.id::text||p_exp::text||d::text) LIMIT 1;
   IF NOT FOUND THEN SELECT * INTO c FROM public.security_missions sm WHERE sm.trip_id IS NULL AND sm.kind='solo' AND (v_age>=21 OR NOT (sm.traveler_tags @> ARRAY['night_owl'])) AND length(btrim(sm.insight))>12 AND NOT (v_age<18 AND (sm.text||' '||sm.title) ~* '(stranger|passer|after dark|late at night|photograph.*(local|person|people))') ORDER BY md5(sm.id::text||p_exp::text||d::text) LIMIT 1; END IF;
   IF NOT FOUND THEN RAISE EXCEPTION 'No safe quest available'; END IF;
  END IF;
  v_title:=replace(c.title,'{destination}',v_dest);
  IF EXISTS(SELECT 1 FROM public.solo_quests q WHERE q.user_id=auth.uid() AND lower(q.title)=lower(v_title)) THEN v_title:=left(v_title,85)||' · Day '||d::text; END IF;
  v_text:=replace(c.text,'{destination}',v_dest);
  IF EXISTS(SELECT 1 FROM public.solo_quests q JOIN public.culture_experiences x ON x.id=q.experience_id WHERE q.user_id=auth.uid() AND x.country=e.country AND x.culture_layer IS NOT DISTINCT FROM e.culture_layer AND q.mission_text=replace(c.text,'{destination}',v_dest)) THEN v_text:=v_text||' For day '||d::text||', choose a different real example, trace its origin using local voices, and compare what you learned with your earlier work.'; END IF; IF d<1 THEN v_text:='Before you travel, research or safely try this from home: '||v_text; END IF;
  INSERT INTO public.solo_quests(experience_id,user_id,day_number,title,mission_text,backstory,keywords,insight,lens,budget_note)
   VALUES(p_exp,auth.uid(),d,v_title,v_text,replace(c.backstory,'{destination}',v_dest),ARRAY(SELECT replace(k,'{destination}',v_dest) FROM unnest(c.keywords) k),replace(c.insight,'{destination}',v_dest),c.category,c.budget_note)
   ON CONFLICT DO NOTHING;
 END LOOP;
END $$;


--
-- Name: accept_legal(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.accept_legal(p_version text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_created timestamptz; v_open boolean; v_closed timestamptz; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF p_version <> '2026-10-03' THEN RAISE EXCEPTION 'Please review the current terms'; END IF; SELECT created_at INTO v_created FROM auth.users WHERE id=auth.uid(); SELECT founding_open,founding_closed_at INTO v_open,v_closed FROM public.app_settings LIMIT 1; INSERT INTO public.account_consents(user_id,legal_version,accepted_at,founding_member) VALUES(auth.uid(),p_version,now(),coalesce(v_open,false) OR (v_closed IS NOT NULL AND v_created < v_closed)) ON CONFLICT(user_id) DO UPDATE SET legal_version=excluded.legal_version,accepted_at=excluded.accepted_at,updated_at=now(),founding_member=public.account_consents.founding_member OR excluded.founding_member; END $$;


--
-- Name: account_status(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.account_status() RETURNS TABLE(legal_version text, accepted_at timestamp with time zone, founding_member boolean, founding_open boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT c.legal_version,c.accepted_at,coalesce(c.founding_member,false),coalesce(s.founding_open,false) FROM public.app_settings s LEFT JOIN public.account_consents c ON c.user_id=auth.uid() WHERE auth.uid() IS NOT NULL LIMIT 1 $$;


--
-- Name: add_checkin_tasks(uuid, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.add_checkin_tasks(p_trip uuid, p_tasks jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_n int;
BEGIN
  IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can add tasks'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ai_usage WHERE trip_id=p_trip AND user_id=auth.uid() AND kind='mission_topup' AND created_at > now() - interval '10 minutes') THEN RAISE EXCEPTION 'Spend credits first'; END IF;
  INSERT INTO public.security_missions(kind,category,title,text,backstory,keywords,trip_id)
    SELECT 'checkin', left(coalesce(nullif(trim(e->>'category'),''),'Fresh for your trip'),40), left(trim(e->>'title'),80), left(trim(e->>'what'),240), left(trim(coalesce(e->>'backstory','')),400),
      (SELECT array_agg(left(trim(k),60)) FROM (SELECT jsonb_array_elements_text(coalesce(e->'keywords','[]'::jsonb)) k LIMIT 4) kk), p_trip
    FROM (SELECT e FROM jsonb_array_elements(p_tasks) e LIMIT 10) s
    WHERE length(trim(coalesce(e->>'title',''))) > 2 AND length(trim(coalesce(e->>'what',''))) > 10
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT; RETURN v_n;
END $$;


--
-- Name: add_trip_missions(uuid, text[]); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.add_trip_missions(p_trip uuid, p_texts text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_kind text; v_n int;
BEGIN
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.ai_usage WHERE trip_id=p_trip AND user_id=auth.uid() AND kind='mission_topup' AND created_at > now() - interval '10 minutes') THEN RAISE EXCEPTION 'Spend credits first'; END IF;
  SELECT CASE WHEN kind IN ('at_home','cultural_inspiration') THEN 'home' ELSE 'trip' END INTO v_kind FROM public.trips WHERE id=p_trip;
  INSERT INTO public.security_missions(kind,category,text,trip_id)
    SELECT v_kind, 'Fresh for your trip', left(trim(t),200), p_trip FROM unnest(p_texts[1:10]) t WHERE length(trim(t)) > 5
    ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT; RETURN v_n;
END $$;


--
-- Name: adult_badge(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.adult_badge(p_trip uuid, p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT trip_private.is_trip_member(p_trip,auth.uid()) AND EXISTS (SELECT 1 FROM public.trips t JOIN public.trip_adult_approvals a ON a.trip_id=t.id AND a.user_id=p_user WHERE t.id=p_trip AND t.vibe='party' AND NOT t.has_minors AND trip_private.is_trip_member(p_trip,p_user) AND coalesce(trip_private.age_of(p_user),0)>=21) $$;


--
-- Name: adult_settings_minor_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.adult_settings_minor_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.enabled AND EXISTS (SELECT 1 FROM public.trips t WHERE t.id=NEW.trip_id AND t.has_minors) THEN NEW.enabled := false; END IF;
 RETURN NEW;
END $$;


--
-- Name: advance_play_phase(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.advance_play_phase(p_trip uuid, p_current integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_current integer; v_next integer;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can move the phase'; END IF;
 IF p_current NOT BETWEEN 0 AND 2 THEN RAISE EXCEPTION 'Invalid phase'; END IF;
 INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT(trip_id) DO NOTHING;
 SELECT play_phase_override INTO v_current FROM public.trip_play_state WHERE trip_id=p_trip FOR UPDATE;
 IF v_current IS NOT NULL AND v_current <> p_current THEN RAISE EXCEPTION 'The phase changed; refresh and try again'; END IF;
 v_next := p_current + 1;
 UPDATE public.trip_play_state SET play_phase_override=v_next, updated_at=now() WHERE trip_id=p_trip;
 RETURN v_next;
END $$;


--
-- Name: age_of(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.age_of(p_user uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN EXISTS (SELECT 1 FROM trip_private.lab_views v WHERE v.user_id=p_user AND v.view='teen') THEN 15
    ELSE (SELECT extract(year FROM age(current_date, dob))::int FROM public.player_private WHERE user_id = p_user) END $$;


--
-- Name: age_range(integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.age_range(p_age integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE WHEN p_age IS NULL THEN 'Unknown' WHEN p_age < 18 THEN 'Teen 13–17' WHEN p_age < 21 THEN '18–20' ELSE '21+' END $$;


--
-- Name: ai_cost_per_trip(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ai_cost_per_trip() RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r numeric; BEGIN
 IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Not allowed'; END IF;
 SELECT round(avg(s),4) INTO r FROM (SELECT sum(coalesce(est_cost_usd,0)) s FROM public.ai_usage WHERE trip_id IS NOT NULL AND created_at >= now() - interval '30 days' GROUP BY trip_id) x;
 RETURN coalesce(r,0); END $$;


--
-- Name: ai_cost_summary(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ai_cost_summary() RETURNS TABLE(action text, calls integer, credits integer, avg_cost_usd numeric, total_cost_usd numeric, avg_in integer, avg_out integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Not allowed'; END IF;
 RETURN QUERY SELECT u.kind, count(*)::int, coalesce(sum(u.credits),0)::int, round(avg(u.est_cost_usd),5), round(coalesce(sum(u.est_cost_usd),0),4), avg(u.input_tokens)::int, avg(u.output_tokens)::int
  FROM public.ai_usage u WHERE u.created_at >= now() - interval '30 days' GROUP BY u.kind ORDER BY 5 DESC;
END $$;


--
-- Name: ai_daily_counts(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ai_daily_counts() RETURNS TABLE(day date, user_id uuid, calls bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; RETURN QUERY SELECT (u.created_at AT TIME ZONE 'UTC')::date,u.user_id,count(*) FROM public.ai_usage u WHERE u.created_at>=now()-interval '30 days' GROUP BY 1,2 ORDER BY 1 DESC,3 DESC; END $$;


--
-- Name: ai_gate(text, uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ai_gate(p_kind text, p_trip uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE s record; n int;
BEGIN
  SELECT ai_enabled, ai_daily_global_cap, ai_daily_user_cap INTO s FROM public.app_settings LIMIT 1;
  IF s IS NULL THEN RETURN; END IF;
  IF NOT s.ai_enabled THEN RAISE EXCEPTION 'AI_PAUSED: AI ideas are taking a break — pre-written content keeps playing.'; END IF;
  SELECT count(*) INTO n FROM public.ai_usage WHERE created_at >= date_trunc('day', now());
  IF n >= s.ai_daily_global_cap THEN RAISE EXCEPTION 'AI_DAILY_CAP: AI ideas are taking a break — pre-written content keeps playing.'; END IF;
  IF p_user IS NOT NULL THEN
    SELECT count(*) INTO n FROM public.ai_usage WHERE user_id = p_user AND created_at >= date_trunc('day', now());
    IF n >= s.ai_daily_user_cap THEN RAISE EXCEPTION 'AI_USER_CAP: AI ideas are taking a break — pre-written content keeps playing.'; END IF;
  END IF;
END $$;


--
-- Name: ai_guard_report(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.ai_guard_report() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb; t0 timestamptz := date_trunc('day', now()); w0 timestamptz := date_trunc('day', now()) - interval '6 days';
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  SELECT jsonb_build_object(
    'settings', (SELECT jsonb_build_object('enabled', ai_enabled, 'global_cap', ai_daily_global_cap, 'user_cap', ai_daily_user_cap, 'updated_at', ai_updated_at) FROM public.app_settings LIMIT 1),
    'today', (SELECT jsonb_build_object('calls', count(*), 'credits', coalesce(sum(credits),0), 'input', coalesce(sum(input_tokens),0), 'output', coalesce(sum(output_tokens),0)) FROM public.ai_usage WHERE created_at >= t0),
    'week', (SELECT jsonb_build_object('calls', count(*), 'credits', coalesce(sum(credits),0), 'input', coalesce(sum(input_tokens),0), 'output', coalesce(sum(output_tokens),0)) FROM public.ai_usage WHERE created_at >= w0),
    'top_trips', coalesce((SELECT jsonb_agg(x) FROM (SELECT u.trip_id, t.name, count(*) calls FROM public.ai_usage u LEFT JOIN public.trips t ON t.id=u.trip_id WHERE u.created_at >= t0 AND u.trip_id IS NOT NULL GROUP BY u.trip_id, t.name ORDER BY calls DESC LIMIT 5) x), '[]'),
    'top_users', coalesce((SELECT jsonb_agg(x) FROM (SELECT u.user_id, p.display_name AS name, count(*) calls FROM public.ai_usage u LEFT JOIN public.profiles p ON p.id=u.user_id WHERE u.created_at >= t0 AND u.user_id IS NOT NULL GROUP BY u.user_id, p.display_name ORDER BY calls DESC LIMIT 5) x), '[]'),
    'recent', coalesce((SELECT jsonb_agg(x) FROM (SELECT u.kind, t.name AS trip, p.display_name AS name, u.input_tokens, u.output_tokens, u.credits, u.created_at FROM public.ai_usage u LEFT JOIN public.trips t ON t.id=u.trip_id LEFT JOIN public.profiles p ON p.id=u.user_id ORDER BY u.created_at DESC LIMIT 20) x), '[]')
  ) INTO r;
  RETURN r;
END $$;


--
-- Name: answer_trivia(uuid, date, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.answer_trivia(p_trip uuid, p_date date, p_question integer, p_choice integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE g public.trip_day_games := trip_private.play_day(p_trip,p_date); v_ok boolean; BEGIN PERFORM trip_private.require_feature(p_trip, 'challenges'); IF g.tag<>'Chill' OR p_question NOT BETWEEN 0 AND 5 OR p_choice NOT BETWEEN 0 AND 3 THEN RAISE EXCEPTION 'No trivia today'; END IF; IF EXISTS(SELECT 1 FROM public.trivia_answers WHERE trip_id=p_trip AND day_date=p_date AND user_id=auth.uid() AND question=p_question) THEN RAISE EXCEPTION 'Already answered'; END IF; IF p_question=0 AND trip_private.is_approved_adult(p_trip,auth.uid()) AND EXISTS(SELECT 1 FROM public.trip_adult_activities WHERE trip_id=p_trip AND day_date=p_date AND kind='trivia') THEN v_ok:=p_choice=1; ELSE SELECT (answers->>p_question)::int=p_choice INTO v_ok FROM public.trip_day_trivia_keys WHERE trip_id=p_trip AND day_date=p_date; END IF; v_ok:=coalesce(v_ok,false); INSERT INTO public.trivia_answers(trip_id,day_date,user_id,question,choice,correct) VALUES(p_trip,p_date,auth.uid(),p_question,p_choice,v_ok); RETURN v_ok; END $$;


--
-- Name: answer_weekly_question(uuid, integer, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.answer_weekly_question(p_trip uuid, p_week integer, p_answer text, p_emoji text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE q public.weekly_questions; s timestamptz; BEGIN PERFORM trip_private.require_feature(p_trip, 'qotw');
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
IF EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND ended_at IS NOT NULL) THEN RAISE EXCEPTION 'This trip has ended'; END IF;
SELECT * INTO q FROM public.weekly_questions WHERE trip_id=p_trip AND week_number=p_week;
IF NOT FOUND OR q.drops_at > now() THEN RAISE EXCEPTION 'This question hasn''t dropped yet'; END IF;
IF p_week >= 1000 THEN s := q.drops_at + trip_private.bonus_window(p_trip); ELSE SELECT starts_at INTO s FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week; END IF;
IF q.revealed_at IS NOT NULL OR s <= now() THEN RAISE EXCEPTION 'Answers are locked for this question'; END IF;
IF length(trim(coalesce(p_answer,''))) NOT BETWEEN 1 AND 200 THEN RAISE EXCEPTION 'Answers are 1 to 200 characters'; END IF;
INSERT INTO public.weekly_answers(trip_id, week_number, user_id, answer, emoji) VALUES (p_trip, p_week, auth.uid(), trim(p_answer), nullif(trim(coalesce(p_emoji,'')),''))
ON CONFLICT (trip_id, week_number, user_id) DO UPDATE SET answer=EXCLUDED.answer, emoji=EXCLUDED.emoji; END $$;


--
-- Name: apply_game_plan(uuid, text, integer, time without time zone, date, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.apply_game_plan(p_trip uuid, p_plan text, p_weekday integer, p_time time without time zone, p_start date, p_every integer, p_count integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_count int; v_host uuid; v_keep int; t public.trips; v_today date; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE status='approved' AND trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can confirm a game plan'; END IF;
SELECT * INTO t FROM public.trips WHERE id=p_trip; v_today := (now() AT TIME ZONE t.home_timezone)::date;
CREATE TEMP TABLE IF NOT EXISTS _gplan(week_number int, starts_at timestamptz, kept boolean) ON COMMIT DROP; TRUNCATE _gplan;
INSERT INTO _gplan SELECT * FROM trip_private.plan_game_nights(p_trip,p_plan,p_weekday,p_time,p_start,p_every,p_count);
IF NOT EXISTS (SELECT 1 FROM _gplan) THEN RAISE EXCEPTION 'A season needs at least 1 game night before the trip'; END IF;
SELECT coalesce(max(week_number) FILTER (WHERE kept),0) INTO v_keep FROM _gplan;
SELECT count(*) INTO v_count FROM public.trip_members WHERE status='approved' AND trip_id=p_trip;
DELETE FROM public.host_swaps s WHERE s.trip_id=p_trip AND s.week_number > v_keep AND s.status='open';
DELETE FROM public.game_night_flow f WHERE f.trip_id=p_trip AND f.week_number > v_keep;
DELETE FROM public.weekly_questions q WHERE q.trip_id=p_trip AND q.drops_at > now() AND ((q.week_number > v_keep AND q.week_number < 1000) OR q.week_number >= 1000);
DELETE FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number > v_keep;
FOR r IN SELECT * FROM _gplan WHERE NOT kept ORDER BY week_number LOOP
  SELECT user_id INTO v_host FROM public.trip_members WHERE status='approved' AND trip_id=p_trip ORDER BY coalesce(approved_at,joined_at),user_id LIMIT 1 OFFSET ((r.week_number-1)%greatest(v_count,1));
  INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,r.week_number,r.starts_at,v_host);
END LOOP;
UPDATE public.trips SET game_plan=p_plan, schedule_every=CASE WHEN p_plan='custom' AND p_every=2 THEN 2 ELSE 1 END,
  game_start = CASE WHEN p_plan='custom' THEN greatest(p_start, v_today)
                    WHEN p_plan='short' THEN coalesce((SELECT min((starts_at AT TIME ZONE home_timezone)::date) FROM public.game_nights WHERE trip_id=p_trip AND starts_at > now()), v_today)
                    ELSE greatest(v_today, start_date - 84) END
  WHERE id=p_trip;
UPDATE public.trips SET game_start = least(game_start, (SELECT min((starts_at AT TIME ZONE home_timezone)::date) FROM public.game_nights WHERE trip_id=p_trip)) WHERE id=p_trip;
UPDATE public.game_night_polls SET confirmed_option=coalesce(confirmed_option,0) WHERE trip_id=p_trip;
PERFORM trip_private.ensure_weekly_questions(p_trip);
RETURN (SELECT count(*) FROM _gplan)::int; END $$;


--
-- Name: apply_join_baseline(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.apply_join_baseline(p_trip uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; gr trip_private.trip_join_grants%ROWTYPE; v_avg int := 0; v_week int; v_closed boolean; v_trip_avg int := 0; BEGIN
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 SELECT * INTO gr FROM trip_private.trip_join_grants WHERE trip_id=p_trip AND user_id=p_user;
 IF FOUND THEN
   UPDATE public.trip_members SET start_stamps=gr.start_stamps, joined_week=gr.joined_week, trip_start_stamps=gr.trip_start_stamps, season_closed=gr.season_closed WHERE trip_id=p_trip AND user_id=p_user;
   RETURN;
 END IF;
 v_closed := EXISTS (SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season='game') OR coalesce(trip_private.effective_crowning(p_trip,'game') <= now(), false);
 IF NOT v_closed AND EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND starts_at <= now()) THEN
   SELECT coalesce(floor(avg(g.stamps) FILTER (WHERE g.stamps > 0 AND g.user_id <> p_user)),0)::int INTO v_avg FROM trip_private.game_stamps(p_trip) g;
   SELECT coalesce(min(week_number) FILTER (WHERE starts_at > now()), max(week_number)+1) INTO v_week FROM public.game_nights WHERE trip_id=p_trip;
 END IF;
 IF v_closed AND (now() AT TIME ZONE t.home_timezone)::date > t.start_date AND trip_private.is_trip_member(p_trip, auth.uid()) THEN
   SELECT coalesce(floor(avg(s.stamps) FILTER (WHERE s.stamps > 0 AND s.user_id <> p_user)),0)::int INTO v_trip_avg FROM trip_private.trip_season(p_trip) s;
 END IF;
 UPDATE public.trip_members SET start_stamps=v_avg, joined_week=v_week, season_closed=v_closed, trip_start_stamps=v_trip_avg WHERE trip_id=p_trip AND user_id=p_user;
 INSERT INTO trip_private.trip_join_grants(trip_id,user_id,start_stamps,joined_week,trip_start_stamps,season_closed) VALUES(p_trip,p_user,v_avg,v_week,v_trip_avg,v_closed);
END $$;


--
-- Name: apply_reschedule(uuid, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.apply_reschedule(p_trip uuid, p_every integer, p_count integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; v_count int; v_host uuid; v_max int; t public.trips; BEGIN
IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE status='approved' AND trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can confirm a new schedule'; END IF;
SELECT * INTO t FROM public.trips WHERE id=p_trip;
CREATE TEMP TABLE IF NOT EXISTS _plan(week_number int, starts_at timestamptz, played boolean) ON COMMIT DROP; TRUNCATE _plan;
INSERT INTO _plan SELECT * FROM trip_private.reschedule_preview(p_trip, p_every, p_count);
IF NOT EXISTS (SELECT 1 FROM _plan) THEN RAISE EXCEPTION 'A season needs at least 1 game night before the trip'; END IF;
SELECT max(week_number) INTO v_max FROM _plan; SELECT count(*) INTO v_count FROM public.trip_members WHERE status='approved' AND trip_id=p_trip;
DELETE FROM public.game_night_flow f WHERE f.trip_id=p_trip AND f.week_number > v_max;
DELETE FROM public.weekly_questions q WHERE q.trip_id=p_trip AND q.week_number > v_max AND q.drops_at > now();
DELETE FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number > v_max AND n.starts_at > now();
FOR r IN SELECT * FROM _plan WHERE NOT played LOOP
  IF EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=r.week_number) THEN
    UPDATE public.game_nights n SET starts_at=r.starts_at WHERE n.trip_id=p_trip AND n.week_number=r.week_number AND n.starts_at IS DISTINCT FROM r.starts_at;
    IF FOUND THEN DELETE FROM public.weekly_questions q WHERE q.trip_id=p_trip AND q.week_number=r.week_number AND q.drops_at > now() AND q.source='pool';
      UPDATE public.weekly_questions q SET drops_at=least(q.drops_at, r.starts_at - interval '1 day') WHERE q.trip_id=p_trip AND q.week_number=r.week_number AND q.drops_at > now(); END IF;
  ELSE
    SELECT user_id INTO v_host FROM public.trip_members WHERE status='approved' AND trip_id=p_trip ORDER BY coalesce(approved_at,joined_at),user_id LIMIT 1 OFFSET ((r.week_number-1)%greatest(v_count,1));
    INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,r.week_number,r.starts_at,v_host);
  END IF;
END LOOP;
UPDATE public.trips SET schedule_every=greatest(1,least(2,coalesce(p_every,1))) WHERE id=p_trip;
PERFORM trip_private.ensure_weekly_questions(p_trip);
RETURN (SELECT count(*) FROM _plan)::int; END $$;


--
-- Name: approve_adult_player(uuid, uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.approve_adult_player(p_trip uuid, p_user uuid, p_approve boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain' AND status='approved') THEN RAISE EXCEPTION 'Captain only'; END IF;
 IF p_approve THEN
  IF NOT trip_private.is_trip_member(p_trip,p_user) OR coalesce(trip_private.age_of(p_user),0)<21 THEN RAISE EXCEPTION 'Player must be 21 or older'; END IF;
  INSERT INTO public.trip_adult_approvals(trip_id,user_id,approved_by) VALUES(p_trip,p_user,auth.uid()) ON CONFLICT(trip_id,user_id) DO UPDATE SET approved_by=excluded.approved_by;
 ELSE DELETE FROM public.trip_adult_approvals WHERE trip_id=p_trip AND user_id=p_user; END IF;
END $$;


--
-- Name: approve_inspiration(uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.approve_inspiration(p_card uuid, p_approve boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trip uuid; BEGIN
 SELECT trip_id INTO v_trip FROM public.cultural_inspirations WHERE id=p_card AND captain_approved_at IS NULL;
 IF v_trip IS NULL OR NOT trip_private.is_captain(v_trip) THEN RAISE EXCEPTION 'Only the Captain can approve this experience'; END IF;
 IF p_approve THEN PERFORM set_config('trip.approving','on',true); UPDATE public.cultural_inspirations SET captain_approved_at=now() WHERE id=p_card; PERFORM set_config('trip.approving','',true);
 ELSE DELETE FROM public.cultural_inspirations WHERE id=p_card; END IF; END $$;


--
-- Name: approve_member(uuid, uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.approve_member(p_trip uuid, p_user uuid, p_approve boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can approve members'; END IF;
 IF p_user=auth.uid() THEN RAISE EXCEPTION 'You can''t approve yourself'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_user AND status='pending') THEN RAISE EXCEPTION 'That request is no longer waiting'; END IF;
 IF p_approve THEN
  IF coalesce(trip_private.age_of(p_user),0) < 18 AND NOT EXISTS (SELECT 1 FROM public.sandbox_bots WHERE user_id=p_user) THEN
    IF EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND vibe='party') THEN RAISE EXCEPTION 'Party trips aren''t open to players under 18'; END IF;
    IF EXISTS (SELECT 1 FROM public.trips WHERE id=p_trip AND season_rule='a2c') THEN
      UPDATE public.trips SET vibe='family', has_minors=true WHERE id=p_trip;
      UPDATE public.trip_adult_settings SET enabled=false WHERE trip_id=p_trip;
    END IF;
  END IF;
  UPDATE public.trip_members SET status='approved', approved_at=now() WHERE trip_id=p_trip AND user_id=p_user;
  DELETE FROM trip_private.trip_removals WHERE trip_id=p_trip AND user_id=p_user;
  PERFORM trip_private.apply_join_baseline(p_trip, p_user);
  INSERT INTO public.beta_access(user_id, source) VALUES (p_user, 'invite') ON CONFLICT DO NOTHING;
 ELSE DELETE FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_user; END IF; END $$;


--
-- Name: archive_legacy_trips(timestamp with time zone, uuid[], text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.archive_legacy_trips(p_created_before timestamp with time zone, p_keep uuid[], p_note text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n integer;
BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'App admins only'; END IF;
  IF p_created_before IS NULL THEN RAISE EXCEPTION 'Choose a cutover time'; END IF;
  WITH changed AS (
    UPDATE public.trips SET rules_version = 1
    WHERE rules_version = 2 AND created_at < p_created_before AND id <> ALL (coalesce(p_keep, '{}'))
    RETURNING id
  )
  INSERT INTO trip_private.trip_archive_log (trip_id, archived, changed_by, note)
  SELECT id, true, auth.uid(), p_note FROM changed;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;


--
-- Name: at_home_add(uuid, date, text, text, text, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_add(p_trip uuid, p_day date, p_kind text, p_cat text, p_extra text DEFAULT NULL::text, p_call boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE tz text := (SELECT home_timezone FROM public.trips WHERE id=p_trip); v_item int; v_extra int; BEGIN PERFORM trip_private.require_feature(p_trip, 'at_home');
  v_item := CASE WHEN p_cat IS NULL THEN NULL ELSE trip_private.at_home_pick(p_trip, p_cat) END;
  INSERT INTO public.at_home_activities(trip_id,day_date,kind,item_id,starts_at,game_number) VALUES (p_trip,p_day,p_kind,v_item,
    CASE WHEN p_call THEN (p_day + time '19:00') AT TIME ZONE tz END,
    CASE WHEN p_kind='call_night' THEN (SELECT number FROM public.game_catalog ORDER BY random() LIMIT 1) END);
  IF p_extra IS NOT NULL THEN
    v_extra := trip_private.at_home_pick(p_trip, p_extra);
    UPDATE public.at_home_activities SET extra_item_id=v_extra WHERE trip_id=p_trip AND day_date=p_day AND kind=p_kind AND extra_item_id IS NULL;
  END IF;
END $$;


--
-- Name: at_home_answer(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_answer(p_activity uuid, p_answer text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; BEGIN
  a := trip_private.at_home_released(p_activity);
  IF a.kind <> 'question' OR a.revealed_at IS NOT NULL THEN RAISE EXCEPTION 'Answers are closed'; END IF;
  IF length(trim(coalesce(p_answer,''))) NOT BETWEEN 1 AND 280 THEN RAISE EXCEPTION 'Write a short answer'; END IF;
  INSERT INTO public.at_home_answers(activity_id,user_id,answer) VALUES (p_activity,auth.uid(),trim(p_answer))
  ON CONFLICT (activity_id,user_id) DO UPDATE SET answer=EXCLUDED.answer;
END $$;


--
-- Name: at_home_cap(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_cap() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF (SELECT kind FROM public.trips WHERE id=NEW.trip_id) = 'at_home' AND (SELECT count(*) FROM public.trip_members WHERE trip_id=NEW.trip_id) >= 12 THEN
    RAISE EXCEPTION 'At Home experiences fit up to 12 people';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: at_home_mark_winner(uuid, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_mark_winner(p_activity uuid, p_user uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; BEGIN
  a := trip_private.at_home_released(p_activity);
  IF NOT trip_private.is_leader(a.trip_id) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can mark a winner'; END IF;
  IF a.kind NOT IN ('call_night','cook','build') THEN RAISE EXCEPTION 'Winners are for game nights and challenges'; END IF;
  IF p_user IS NOT NULL AND NOT trip_private.is_trip_member(a.trip_id, p_user) THEN RAISE EXCEPTION 'Pick someone in the squad'; END IF;
  UPDATE public.at_home_activities SET winner_id=p_user, updated_at=now() WHERE id=a.id;
END $$;


--
-- Name: at_home_move_call(uuid, timestamp with time zone); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_move_call(p_activity uuid, p_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; t public.trips; BEGIN
  SELECT * INTO a FROM public.at_home_activities WHERE id=p_activity;
  IF NOT FOUND OR NOT trip_private.is_captain(a.trip_id) THEN RAISE EXCEPTION 'Only the Captain can move a call'; END IF;
  IF a.starts_at IS NULL THEN RAISE EXCEPTION 'This activity has no call time'; END IF;
  SELECT * INTO t FROM public.trips WHERE id=a.trip_id;
  IF (p_at AT TIME ZONE t.home_timezone)::date NOT BETWEEN t.start_date AND t.end_date THEN RAISE EXCEPTION 'Keep it inside the experience dates'; END IF;
  UPDATE public.at_home_activities SET starts_at=p_at, day_date=(p_at AT TIME ZONE t.home_timezone)::date, updated_at=now() WHERE id=a.id;
END $$;


--
-- Name: at_home_mvp(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_mvp(p_trip uuid) RETURNS TABLE(user_id uuid, points integer, wins integer, votes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t public.trips; v_today date; BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this experience first'; END IF; SELECT * INTO t FROM public.trips WHERE id=p_trip; SELECT p.today INTO v_today FROM trip_private.at_home_plan(p_trip) p LIMIT 1; IF t.ended_at IS NULL AND coalesce(v_today,current_date)<t.end_date THEN RETURN; END IF; RETURN QUERY WITH w AS (SELECT a.winner_id u,count(*)::int n FROM public.at_home_activities a WHERE a.trip_id=p_trip AND a.winner_id IS NOT NULL GROUP BY 1),v AS (SELECT vt.target_id u,count(*)::int n FROM public.at_home_votes vt JOIN public.at_home_activities a ON a.id=vt.activity_id AND a.trip_id=p_trip AND a.revealed_at IS NOT NULL GROUP BY 1) SELECT m.user_id,(coalesce(w.n,0)*3+coalesce(v.n,0)+coalesce(q.points,0))::int,coalesce(w.n,0),coalesce(v.n,0) FROM public.trip_members m LEFT JOIN w ON w.u=m.user_id LEFT JOIN v ON v.u=m.user_id LEFT JOIN trip_private.season_quest_bonus(p_trip,'preflight') q ON q.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' ORDER BY 2 DESC; END $$;


--
-- Name: at_home_pick(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_pick(p_trip uuid, p_cat text) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT i.id FROM public.at_home_pack_items i JOIN public.trips t ON t.id=p_trip AND i.pack=t.at_home_pack
  WHERE i.category=p_cat AND (NOT i.adult OR t.vibe='party')
  ORDER BY NOT trip_private.in_slice(p_trip, i.id::text), (i.id IN (SELECT a.item_id FROM public.at_home_activities a WHERE a.trip_id=p_trip AND a.item_id IS NOT NULL UNION SELECT a.extra_item_id FROM public.at_home_activities a WHERE a.trip_id=p_trip AND a.extra_item_id IS NOT NULL)),
    (i.id IN (SELECT a.item_id FROM public.at_home_activities a JOIN public.trip_members m ON m.trip_id=a.trip_id AND m.role='captain' JOIN public.trip_members me ON me.trip_id=p_trip AND me.role='captain' AND me.user_id=m.user_id WHERE a.trip_id<>p_trip)),
    random() LIMIT 1 $$;


--
-- Name: at_home_plan(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_plan(p_trip uuid) RETURNS TABLE(id uuid, day_date date, kind text, released boolean, title text, body text, want text, extra_title text, extra_body text, starts_at timestamp with time zone, game_name text, game_how text, winner_id uuid, revealed boolean, answers integer, answered boolean, voted boolean, today date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; v_today date; adult_ok boolean; BEGIN PERFORM trip_private.require_feature(p_trip, 'at_home');
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
  SELECT * INTO t FROM public.trips WHERE trips.id=p_trip;
  BEGIN v_today := (now() AT TIME ZONE coalesce((SELECT nullif(p.time_zone,'') FROM public.profiles p WHERE p.id=auth.uid()), t.home_timezone))::date;
  EXCEPTION WHEN others THEN v_today := (now() AT TIME ZONE t.home_timezone)::date; END;
  IF trip_private.lab_bypass(p_trip) THEN v_today := greatest(v_today, coalesce((SELECT max(a.day_date) FROM public.at_home_activities a WHERE a.trip_id=p_trip), v_today)); END IF;
  adult_ok := t.vibe='party' AND coalesce(public.adult_badge(p_trip, auth.uid()), false);
  RETURN QUERY SELECT a.id, a.day_date, a.kind, a.day_date <= v_today,
    CASE WHEN a.day_date <= v_today THEN i.title END,
    CASE WHEN a.day_date <= v_today THEN CASE WHEN i.adult AND NOT adult_ok THEN i.alt ELSE i.body END END,
    CASE WHEN a.day_date - 2 <= v_today THEN i.want END,
    CASE WHEN a.day_date <= v_today AND NOT (x.adult AND NOT adult_ok) THEN x.title END,
    CASE WHEN a.day_date <= v_today AND NOT (x.adult AND NOT adult_ok) THEN x.body END,
    a.starts_at, g.name, CASE WHEN a.day_date <= v_today THEN g.how_to_play END, a.winner_id, a.revealed_at IS NOT NULL,
    (SELECT count(*)::int FROM public.at_home_answers s WHERE s.activity_id=a.id),
    EXISTS (SELECT 1 FROM public.at_home_answers s WHERE s.activity_id=a.id AND s.user_id=auth.uid()),
    EXISTS (SELECT 1 FROM public.at_home_votes v WHERE v.activity_id=a.id AND v.voter_id=auth.uid()),
    v_today
  FROM public.at_home_activities a LEFT JOIN public.at_home_pack_items i ON i.id=a.item_id LEFT JOIN public.at_home_pack_items x ON x.id=a.extra_item_id LEFT JOIN public.game_catalog g ON g.number=a.game_number
  WHERE a.trip_id=p_trip ORDER BY a.day_date, coalesce(a.starts_at, a.day_date::timestamptz), a.kind;
END $$;


--
-- Name: at_home_question(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_question(p_activity uuid) RETURNS TABLE(idx integer, answer text, mine boolean, user_id uuid, votes integer, my_vote boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; BEGIN
  a := trip_private.at_home_released(p_activity);
  RETURN QUERY SELECT s.rn::int, s.answer, s.user_id=auth.uid(),
    CASE WHEN a.revealed_at IS NOT NULL THEN s.user_id END,
    CASE WHEN a.revealed_at IS NOT NULL THEN (SELECT count(*)::int FROM public.at_home_votes v WHERE v.activity_id=a.id AND v.target_id=s.user_id) END,
    EXISTS (SELECT 1 FROM public.at_home_votes v WHERE v.activity_id=a.id AND v.voter_id=auth.uid() AND v.target_id=s.user_id)
  FROM (SELECT x.user_id, x.answer, row_number() OVER (ORDER BY md5(x.user_id::text || a.id::text)) rn FROM public.at_home_answers x WHERE x.activity_id=a.id) s ORDER BY s.rn;
END $$;


--
-- Name: at_home_activities; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.at_home_activities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    trip_id uuid NOT NULL,
    day_date date NOT NULL,
    kind text NOT NULL,
    item_id integer,
    extra_item_id integer,
    game_number integer,
    starts_at timestamp with time zone,
    winner_id uuid,
    revealed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT at_home_activities_kind_check CHECK ((kind = ANY (ARRAY['takeoff'::text, 'call_night'::text, 'cook'::text, 'build'::text, 'drop'::text, 'question'::text, 'passport'::text])))
);


--
-- Name: at_home_released(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_released(p_activity uuid) RETURNS public.at_home_activities
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; r record; BEGIN
  SELECT * INTO a FROM public.at_home_activities WHERE id=p_activity;
  IF NOT FOUND OR NOT trip_private.is_trip_member(a.trip_id, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
  SELECT * INTO r FROM trip_private.at_home_plan(a.trip_id) p WHERE p.id=p_activity;
  IF NOT r.released THEN RAISE EXCEPTION 'This one isn''t out yet'; END IF;
  RETURN a;
END $$;


--
-- Name: at_home_reveal(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_reveal(p_activity uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; BEGIN
  a := trip_private.at_home_released(p_activity);
  IF NOT trip_private.is_leader(a.trip_id) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can reveal'; END IF;
  UPDATE public.at_home_activities SET revealed_at=coalesce(revealed_at, now()), updated_at=now() WHERE id=a.id;
END $$;


--
-- Name: at_home_tier(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_tier() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; n int; cap uuid; BEGIN
  SELECT * INTO t FROM public.trips WHERE id=NEW.trip_id;
  IF t.kind <> 'at_home' OR NEW.status <> 'approved' OR (now() AT TIME ZONE t.home_timezone)::date >= t.start_date THEN RETURN NEW; END IF;
  SELECT count(*) INTO n FROM public.trip_members WHERE trip_id=t.id AND status='approved';
  IF n > 6 AND EXISTS (SELECT 1 FROM public.orders WHERE trip_id=t.id AND kind='at_home' AND tier='1-6')
     AND NOT EXISTS (SELECT 1 FROM public.orders WHERE trip_id=t.id AND tier='7-12') THEN
    SELECT user_id INTO cap FROM public.trip_members WHERE trip_id=t.id AND role='captain' LIMIT 1;
    INSERT INTO public.orders(trip_id,captain_id,kind,label,tier,list_cents,discount_cents,amount_due_cents,status)
    VALUES (t.id, cap, 'tier_upgrade', 'Group grew to 7–12 people', '7-12', 300, 0, 300, 'beta_free');
  END IF;
  RETURN NEW;
END $$;


--
-- Name: at_home_vote(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.at_home_vote(p_activity uuid, p_idx integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE a public.at_home_activities; v_target uuid; BEGIN
  a := trip_private.at_home_released(p_activity);
  IF a.kind <> 'question' OR a.revealed_at IS NOT NULL THEN RAISE EXCEPTION 'Voting is closed'; END IF;
  SELECT s.user_id INTO v_target FROM (SELECT user_id, row_number() OVER (ORDER BY md5(user_id::text || a.id::text)) rn FROM public.at_home_answers WHERE activity_id=a.id) s WHERE s.rn=p_idx;
  IF v_target IS NULL THEN RAISE EXCEPTION 'Pick an answer'; END IF;
  IF v_target = auth.uid() THEN RAISE EXCEPTION 'You can''t vote for your own answer'; END IF;
  INSERT INTO public.at_home_votes(activity_id,voter_id,target_id) VALUES (a.id,auth.uid(),v_target)
  ON CONFLICT (activity_id,voter_id) DO UPDATE SET target_id=EXCLUDED.target_id;
END $$;


--
-- Name: auto_team_trg(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.auto_team_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE tid uuid; BEGIN
 IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'approved')
    AND NOT EXISTS (SELECT 1 FROM public.trip_team_members WHERE trip_id=NEW.trip_id AND user_id=NEW.user_id) THEN
   SELECT t.id INTO tid FROM public.trip_teams t WHERE t.trip_id=NEW.trip_id
     ORDER BY (SELECT count(*) FROM public.trip_team_members x WHERE x.team_id=t.id), t.created_at LIMIT 1 FOR UPDATE;
   IF tid IS NOT NULL THEN INSERT INTO public.trip_team_members(trip_id,user_id,team_id) VALUES (NEW.trip_id,NEW.user_id,tid) ON CONFLICT DO NOTHING; END IF;
 END IF;
 RETURN NEW; END $$;


--
-- Name: beta_free(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.beta_free() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce((SELECT beta_free FROM public.app_settings ORDER BY id LIMIT 1), true) $$;


--
-- Name: boarding_tile(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.boarding_tile() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce((SELECT boarding_tile FROM public.app_settings LIMIT 1),'current') $$;


--
-- Name: bonus_window(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.bonus_window(p_trip uuid) RETURNS interval
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT interval '2 days' $$;


--
-- Name: bug_report_defaults(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.bug_report_defaults() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN NEW.status := 'new'; NEW.founder_note := NULL; NEW.issue_id := NULL; NEW.status_changed_at := NULL; NEW.update_seen_at := NULL; NEW.app_version := left(NEW.app_version, 40); RETURN NEW; END $$;


--
-- Name: can_manage_teams(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.can_manage_teams(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT trip_private.is_captain(p_trip) OR (trip_private.is_leader(p_trip) AND trip_private.night_live(p_trip)) $$;


--
-- Name: can_run_night(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.can_run_night(p_trip uuid, p_week integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=p_trip AND m.user_id=auth.uid() AND (m.role IN ('captain','co_captain') OR EXISTS (SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND n.week_number=p_week AND n.host_id=auth.uid()))) $$;


--
-- Name: can_run_turns(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.can_run_turns(p_trip uuid, p_week integer) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.game_nights n JOIN public.trip_members m ON m.trip_id=n.trip_id AND m.user_id=auth.uid() WHERE n.trip_id=p_trip AND n.week_number=p_week AND (n.host_id=auth.uid() OR m.role IN ('captain','co_captain'))) $$;


--
-- Name: can_view_culture(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.can_view_culture(p_exp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS (SELECT 1 FROM public.culture_experiences e WHERE e.id=p_exp AND (CASE WHEN e.a2e_kind IS NOT NULL THEN trip_private.a2e_culture_access(e.id) ELSE e.creator_id=auth.uid() OR trip_private.is_app_admin() OR (e.visibility='squad' AND e.trip_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=e.trip_id AND m.user_id=auth.uid() AND m.status='approved')) OR (e.visibility='public' AND e.finished_at IS NOT NULL AND e.unlisted_at IS NULL AND trip_private.has_beta_access()) END)) $$;


--
-- Name: cancel_trip_invite(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.cancel_trip_invite(p_invite uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v uuid; BEGIN SELECT trip_id INTO v FROM public.trip_invites WHERE id=p_invite;
 IF v IS NULL OR NOT trip_private.is_captain(v) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 UPDATE public.trip_invites SET cancelled_at=now() WHERE id=p_invite AND used_at IS NULL AND cancelled_at IS NULL; END $$;


--
-- Name: captain_of(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.captain_of(p_trip uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT user_id FROM public.trip_members WHERE trip_id=p_trip AND role='captain' LIMIT 1 $$;


--
-- Name: captain_pass_limit(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.captain_pass_limit(p_trip uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
SELECT CASE WHEN count(*) <= 8 THEN 2 ELSE 3 END::int FROM public.game_nights WHERE trip_id=p_trip AND NOT skipped AND week_number < 1000 $$;


--
-- Name: captain_status(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.captain_status(p_trip uuid) RETURNS TABLE(captain_id uuid, captain_last_seen timestamp with time zone, can_take_over boolean, can_reclaim boolean, reclaim_until timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 WITH c AS (SELECT m.user_id, p.last_seen_at FROM public.trip_members m LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.trip_id=p_trip AND m.role='captain' LIMIT 1),
 t AS (SELECT * FROM public.trip_role_changes WHERE trip_id=p_trip AND role='captain' AND reason='takeover' ORDER BY created_at DESC LIMIT 1)
 SELECT c.user_id, c.last_seen_at,
   EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='co_captain' AND status='approved') AND coalesce(c.last_seen_at < now()-interval '14 days', false),
   EXISTS (SELECT 1 FROM t WHERE t.from_user=auth.uid() AND t.to_user=c.user_id AND t.created_at > now()-interval '7 days') AND trip_private.is_trip_member(p_trip, auth.uid()),
   (SELECT created_at + interval '7 days' FROM t WHERE t.from_user=auth.uid())
 FROM c WHERE trip_private.is_trip_member(p_trip, auth.uid()) $$;


--
-- Name: captain_trip_ids(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.captain_trip_ids(p_trip uuid) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT o.trip_id FROM public.trip_members c JOIN public.trip_members o ON o.user_id=c.user_id AND o.role='captain' AND o.trip_id<>p_trip
  WHERE c.trip_id=p_trip AND c.role='captain'
$$;


--
-- Name: carry_quest_unlocked(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.carry_quest_unlocked(p_trip uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS(SELECT 1 FROM public.game_nights n WHERE n.trip_id=p_trip AND NOT n.skipped AND n.week_number=(SELECT max(x.week_number) FROM public.game_nights x WHERE x.trip_id=p_trip AND NOT x.skipped) AND n.starts_at+interval '3 hours 30 minutes'<=now()) $$;


--
-- Name: cast_day_vote(uuid, date, text, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.cast_day_vote(p_trip uuid, p_date date, p_kind text, p_choice uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.play_day(p_trip,p_date);
IF p_kind NOT IN ('photo','mvp') THEN RAISE EXCEPTION 'Unknown vote'; END IF;
IF p_choice=auth.uid() THEN RAISE EXCEPTION 'No voting for yourself'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=p_choice AND status='approved') THEN RAISE EXCEPTION 'Pick someone in this trip'; END IF;
IF p_kind='photo' AND NOT EXISTS (SELECT 1 FROM public.photo_posts WHERE trip_id=p_trip AND day_date=p_date AND user_id=p_choice) THEN RAISE EXCEPTION 'They haven''t posted a photo'; END IF;
INSERT INTO public.day_votes(trip_id,day_date,kind,voter_id,choice_id) VALUES (p_trip,p_date,p_kind,auth.uid(),p_choice) ON CONFLICT (trip_id,day_date,kind,voter_id) DO UPDATE SET choice_id=excluded.choice_id; END $$;


--
-- Name: cast_live_vote(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.cast_live_vote(p_vote uuid, p_option integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v public.live_votes; BEGIN
SELECT * INTO v FROM public.live_votes WHERE id=p_vote FOR UPDATE;
IF v.id IS NULL OR NOT trip_private.is_trip_member(v.trip_id, auth.uid()) THEN RAISE EXCEPTION 'Vote not found'; END IF;
IF v.status<>'open' THEN RAISE EXCEPTION 'This vote is closed'; END IF;
IF v.week_number IS NOT NULL AND EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=v.trip_id AND week_number=v.week_number) AND NOT trip_private.night_open(v.trip_id, v.week_number) THEN RAISE EXCEPTION 'Voting is open only while the game night is live'; END IF;
IF p_option < 0 OR p_option >= jsonb_array_length(v.options) THEN RAISE EXCEPTION 'Pick an option'; END IF;
IF v.options->p_option->>'user_id' = auth.uid()::text THEN RAISE EXCEPTION 'Nice try! You can''t vote for yourself'; END IF;
INSERT INTO public.live_vote_ballots(vote_id,user_id,option_index) VALUES (p_vote,auth.uid(),p_option) ON CONFLICT (vote_id,user_id) DO UPDATE SET option_index=EXCLUDED.option_index;
UPDATE public.live_votes SET ballot_count=(SELECT count(*) FROM public.live_vote_ballots WHERE vote_id=p_vote) WHERE id=p_vote; END $$;


--
-- Name: check_trip_length(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.check_trip_length() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.end_date - NEW.start_date + 1 NOT BETWEEN 2 AND 30 AND NOT (NEW.a2e_room AND NEW.season_rule='a2c' AND NEW.kind='trip' AND NEW.end_date-NEW.start_date+1 BETWEEN 1 AND 3650) THEN RAISE EXCEPTION 'Trips can be 2 to 30 days long'; END IF; RETURN NEW; END $$;


--
-- Name: checkout_beta(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.checkout_beta(p_trip uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; q record; v_order uuid; v_code uuid; BEGIN
  IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can check out'; END IF;
  IF NOT trip_private.beta_free() THEN RAISE EXCEPTION 'Checkout isn''t open yet. Nothing was charged.'; END IF;
  SELECT * INTO t FROM public.trips WHERE id=p_trip FOR UPDATE;
  SELECT * INTO q FROM trip_private.order_quote(p_trip);
  IF q.order_id IS NOT NULL THEN RETURN q.order_id; END IF;
  IF t.unlocked_at IS NOT NULL THEN RAISE EXCEPTION 'This trip is already unlocked'; END IF;
  IF q.discount_source = 'captain_code' THEN
    SELECT id INTO v_code FROM public.reward_codes WHERE user_id=auth.uid() AND used_at IS NULL AND expires_at > now() ORDER BY created_at LIMIT 1 FOR UPDATE;
  END IF;
  INSERT INTO public.orders(trip_id,captain_id,kind,label,tier,list_cents,discount_cents,discount_source,amount_due_cents,status,collected_cents,provider_ref)
  VALUES (p_trip, auth.uid(), q.kind, q.label, q.tier, q.list_cents, q.discount_cents, q.discount_source, q.amount_due_cents, 'beta_free', 0, NULL) RETURNING id INTO v_order;
  IF v_code IS NOT NULL THEN UPDATE public.reward_codes SET used_at=now(), used_order=v_order WHERE id=v_code AND user_id=auth.uid(); END IF;
  UPDATE public.trips SET unlocked_at=now(), unlocked_by=auth.uid(), big_group = big_group OR q.tier='big_group' WHERE id=p_trip;
  RETURN v_order;
END $$;


--
-- Name: claim_airport(uuid, date, integer, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.claim_airport(p_trip uuid, p_date date, p_mission integer, p_photo text, p_guess text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ DECLARE g public.trip_day_games := trip_private.play_day(p_trip,p_date); BEGIN PERFORM trip_private.require_feature(p_trip, 'challenges');
IF g.tag<>'Travel' OR NOT (g.airport @> to_jsonb(p_mission)) THEN RAISE EXCEPTION 'That mission isn''t on today'; END IF;
IF NOT trip_private.valid_photo(p_trip,p_photo) THEN RAISE EXCEPTION 'Photo upload failed'; END IF;
IF p_mission=1 THEN
  IF g.wheels_up IS NOT NULL THEN RAISE EXCEPTION 'Guessing is closed'; END IF;
  IF p_guess IS NULL OR p_guess !~ '^([01]?[0-9]|2[0-3]):[0-5][0-9]$' THEN RAISE EXCEPTION 'Enter a time like 14:35'; END IF;
END IF;
INSERT INTO public.airport_claims(trip_id,day_date,user_id,mission,photo_path,guess) VALUES (p_trip,p_date,auth.uid(),p_mission,p_photo,CASE WHEN p_mission=1 THEN p_guess END) ON CONFLICT (trip_id,day_date,user_id,mission) DO UPDATE SET photo_path=coalesce(excluded.photo_path,public.airport_claims.photo_path), guess=coalesce(excluded.guess,public.airport_claims.guess); END $_$;


--
-- Name: clear_song_discs(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.clear_song_discs(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.require_feature(p_trip, 'sing_off');
  IF NOT (trip_private.is_leader(p_trip) OR trip_private.lab_bypass(p_trip)) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can clear the discs'; END IF;
  DELETE FROM public.song_discs WHERE trip_id=p_trip;
END $$;


--
-- Name: close_live_vote(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.close_live_vote(p_vote uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v public.live_votes; BEGIN
SELECT * INTO v FROM public.live_votes WHERE id=p_vote FOR UPDATE;
IF v.id IS NULL OR NOT trip_private.is_leader(v.trip_id) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can close a vote'; END IF;
IF v.status='revealed' THEN RETURN; END IF;
IF EXISTS (SELECT 1 FROM public.live_vote_ballots b WHERE b.vote_id=p_vote) THEN RAISE EXCEPTION 'Votes are in — reveal it instead'; END IF;
UPDATE public.live_votes SET status='revealed', results=(SELECT jsonb_agg(0) FROM generate_series(1,jsonb_array_length(v.options))), revealed_at=now() WHERE id=p_vote;
END $$;


--
-- Name: code_rate_check(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.code_rate_check() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF (SELECT count(*) FROM trip_private.code_attempts WHERE user_id=auth.uid() AND created_at > now() - interval '1 hour') >= 10 THEN
  RAISE EXCEPTION 'Too many tries. Take a breather and try again in an hour.'; END IF; END $$;


--
-- Name: confirm_cost_payment(uuid, uuid, bigint); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.confirm_cost_payment(p_item uuid, p_user uuid, p_paid_cents bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trip uuid; v_old bigint; BEGIN
  SELECT trip_id INTO v_trip FROM public.cost_items WHERE id=p_item;
  IF v_trip IS NULL OR NOT trip_private.is_captain(v_trip) THEN RAISE EXCEPTION 'Only the Captain can confirm payments'; END IF;
  IF p_paid_cents IS NULL OR p_paid_cents < 0 THEN RAISE EXCEPTION 'Enter a paid amount'; END IF;
  SELECT paid_cents INTO v_old FROM public.cost_shares WHERE item_id=p_item AND user_id=p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'That player isn''t in this cost'; END IF;
  UPDATE public.cost_shares SET paid_cents=p_paid_cents, reported_cents=NULL, report_note=NULL, reported_at=NULL WHERE item_id=p_item AND user_id=p_user;
  PERFORM trip_private.log_cost(v_trip, p_item, p_user, 'set paid', p_paid_cents, 'was '||v_old);
END $$;


--
-- Name: confirm_departure(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.confirm_departure(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT trip_private.is_leader(p_trip) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can confirm arrival'; END IF;
 UPDATE public.trips SET departure_confirmed_at=now() WHERE id=p_trip AND play_arrangement IS NOT NULL AND is_sandbox=false AND departure_confirmed_at IS NULL AND start_date <= trip_private.trip_today(p_trip);
 IF NOT FOUND THEN RAISE EXCEPTION 'Arrival can only be confirmed once, on or after your first trip day'; END IF;
END $$;


--
-- Name: confirm_game_nights(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.confirm_game_nights(p_trip uuid, p_option integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_start timestamptz; t public.trips; v_host uuid; v_count integer; p record; v_local timestamp; v_gap int; v_take timestamp; v_list timestamp[] := '{}'; x timestamp; i int := 0; BEGIN
IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can confirm'; END IF;
SELECT (options->>p_option)::timestamptz INTO v_start FROM public.game_night_polls WHERE trip_id=p_trip AND confirmed_option IS NULL;
IF v_start IS NULL OR v_start <= now() THEN RAISE EXCEPTION 'Choose a future option'; END IF;
SELECT * INTO t FROM public.trips WHERE id=p_trip;
IF (v_start AT TIME ZONE t.home_timezone)::date >= t.start_date THEN RAISE EXCEPTION 'Time must be before the trip'; END IF;
SELECT count(*) INTO v_count FROM public.trip_members WHERE trip_id=p_trip AND status='approved'; IF v_count=0 THEN RAISE EXCEPTION 'Trip has no members'; END IF;
DELETE FROM public.game_nights WHERE trip_id=p_trip;
v_local := v_start AT TIME ZONE t.home_timezone;
WHILE v_local::date < t.start_date - 84 LOOP v_local := v_local + interval '7 days'; END LOOP;
IF t.start_date - v_local::date < 14 THEN
  FOR p IN SELECT * FROM trip_private.plan_nights(p_trip, v_start, t.schedule_every, NULL) LOOP v_list := v_list || (p.starts_at AT TIME ZONE t.home_timezone); END LOOP;
ELSE
  v_gap := 7 * greatest(1, least(2, coalesce(t.schedule_every,1)));
  v_take := v_local + make_interval(days => ((t.start_date - 1 - v_local::date) / v_gap) * v_gap);
  x := v_take;
  WHILE x >= v_local AND cardinality(v_list) < 12 LOOP v_list := x || v_list; x := x - make_interval(days => v_gap); END LOOP;
END IF;
FOREACH x IN ARRAY v_list LOOP
  i := i + 1;
  SELECT user_id INTO v_host FROM public.trip_members WHERE trip_id=p_trip AND status='approved' ORDER BY coalesce(approved_at,joined_at),user_id LIMIT 1 OFFSET ((i-1)%v_count);
  INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(p_trip,i,x AT TIME ZONE t.home_timezone,v_host);
END LOOP;
IF NOT EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip) THEN RAISE EXCEPTION 'Pick a time before the trip'; END IF;
UPDATE public.trips SET game_start=(SELECT min((starts_at AT TIME ZONE home_timezone)::date) FROM public.game_nights WHERE trip_id=p_trip) WHERE id=p_trip;
UPDATE public.game_night_polls SET confirmed_option=p_option WHERE trip_id=p_trip;
PERFORM trip_private.ensure_weekly_questions(p_trip); END $$;


--
-- Name: content_feedback_summary(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.content_feedback_summary() RETURNS TABLE(kind text, item_text text, ups integer, downs integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
RETURN QUERY SELECT f.kind, max(f.item_text), count(*) FILTER (WHERE f.vote=1)::int, count(*) FILTER (WHERE f.vote=-1)::int
  FROM public.content_feedback f GROUP BY f.kind, f.item_key ORDER BY count(*) DESC LIMIT 200;
END $$;


--
-- Name: content_text_safe(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.content_text_safe(p_text text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ SELECT coalesce(p_text,'') !~* '(hangover|drunk|wasted|blackout|chang toast|starbucks|mcdonald|coca.cola|budweiser|nigg[a-z]*|fagg?[a-z]*|cunt[a-z]*|retard[a-z]*|rape[a-z]*|nazi[a-z]*|dress (up )?like (a|an|the) [a-z]+)' $$;


--
-- Name: create_at_home(text, text, date, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_at_home(p_pack text, p_length text, p_start date, p_vibe text, p_tz text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_trip uuid; v_end date; v_name text; attempt int; tz text := coalesce(nullif(trim(p_tz),''),'UTC'); v_days int; BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 IF coalesce(trip_private.age_of(auth.uid()),0)<18 THEN RAISE EXCEPTION 'At Home is for players 18 and older.'; END IF;
 IF NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'TripJunkies is invite-only during the private beta'; END IF;
 PERFORM now() AT TIME ZONE tz;
 SELECT name INTO v_name FROM public.at_home_packs WHERE key=p_pack;
 IF v_name IS NULL THEN RAISE EXCEPTION 'Pick a destination'; END IF;
 IF p_length ~ '^d([1-9]|1[0-2])$' THEN v_days := substring(p_length from 2)::int;
 ELSIF p_length IN ('weekend','week','two_weeks') THEN v_days := CASE p_length WHEN 'weekend' THEN 3 WHEN 'week' THEN 7 ELSE 14 END;
 ELSE RAISE EXCEPTION 'Pick 1 to 12 days'; END IF;
 IF p_vibe NOT IN ('family','chill','party') THEN RAISE EXCEPTION 'Pick a vibe'; END IF;
 IF p_vibe='party' AND coalesce(trip_private.age_of(auth.uid()),0)<21 THEN RAISE EXCEPTION 'Party vibe needs a Captain who is 21+'; END IF;
 IF p_start IS NULL OR p_start < (now() AT TIME ZONE tz)::date+1 OR p_start > (now() AT TIME ZONE tz)::date+365 THEN RAISE EXCEPTION 'Choose a date at least one day ahead'; END IF;
 IF p_length='weekend' AND extract(isodow FROM p_start)<>5 THEN RAISE EXCEPTION 'Weekend experiences start on a Friday'; END IF;
 v_end := p_start+v_days-1;
 FOR attempt IN 1..15 LOOP BEGIN
 INSERT INTO public.trips(name,destination,start_date,end_date,home_timezone,trip_timezone,join_code,kind,at_home_pack,at_home_length,season_scoring,vibe)
 VALUES(v_name||' at Home',v_name||' (at home)',p_start,v_end,tz,tz,public.new_trip_code(),'at_home',p_pack,p_length,false,p_vibe) RETURNING id INTO v_trip;
 EXIT;
 EXCEPTION WHEN unique_violation THEN IF attempt=15 THEN RAISE; END IF; END; END LOOP;
 INSERT INTO public.trip_members(trip_id,user_id,role,approved_at) VALUES(v_trip,auth.uid(),'captain',now());
 IF p_length LIKE 'd%' THEN
   INSERT INTO public.home_day_sessions(trip_id,day_date,starts_at,card_id)
   SELECT v_trip,p_start+g.n,(p_start+g.n+time '19:00') AT TIME ZONE tz,
    (SELECT i.id FROM public.at_home_pack_items i WHERE i.pack=p_pack AND NOT i.adult AND i.category IN ('dish','order_in','phrase','build','culture','dress_up','playlist','movie','snack') ORDER BY md5(i.id::text||v_trip::text) OFFSET g.n LIMIT 1)
   FROM generate_series(0,v_days-1) AS g(n);
 ELSE PERFORM trip_private.plan_at_home(v_trip); END IF;
 RETURN v_trip;
END $_$;


--
-- Name: create_at_home_a2c(text, integer, date, text, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_at_home_a2c(p_pack text, p_days integer, p_start date, p_vibe text, p_tz text, p_format text, p_place text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; t public.trips; v_final timestamptz; v_mid date;
BEGIN
 IF coalesce(trip_private.age_of(auth.uid()),0)<21 THEN RAISE EXCEPTION 'Captains are 21+. Ask an adult in your squad to set this up.'; END IF;
 IF p_days NOT BETWEEN 2 AND 7 OR p_format NOT IN ('finale','two_nights') THEN RAISE EXCEPTION 'Choose 2–7 days and a finale format'; END IF;
 IF p_format='two_nights' AND p_days<4 THEN RAISE EXCEPTION 'Two game nights need at least four days'; END IF;
 IF length(trim(coalesce(p_place,''))) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'Set a place for the finale'; END IF;
 v_id:=trip_private.create_at_home(p_pack,'d'||p_days::text,p_start,p_vibe,p_tz);
 SELECT * INTO t FROM public.trips WHERE id=v_id;
 v_final:=(t.end_date+time '19:00') AT TIME ZONE t.home_timezone;
 UPDATE public.trips SET season_rule='a2c',finale_format=p_format,finale_place=trim(p_place),finale_at=v_final,game_start=greatest(t.start_date-7,(now() AT TIME ZONE t.home_timezone)::date) WHERE id=v_id AND season_rule='legacy';
 IF p_format='two_nights' THEN
   v_mid:=t.start_date+(p_days/2)-1;
   INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(v_id,1,(v_mid+time '19:00') AT TIME ZONE t.home_timezone,auth.uid());
   INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(v_id,2,v_final,auth.uid());
 ELSE
   INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(v_id,1,v_final,auth.uid());
 END IF;
 RETURN v_id;
END $$;


--
-- Name: create_beta_codes(integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_beta_codes(p_count integer, p_note text) RETURNS SETOF text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n int := 0; v text; tries int := 0; BEGIN
  IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
  IF p_count IS NULL OR p_count < 1 OR p_count > 20 THEN RAISE EXCEPTION 'Make 1 to 20 codes at a time'; END IF;
  WHILE n < p_count AND tries < 200 LOOP
    tries := tries + 1; v := trip_private.new_beta_code();
    BEGIN INSERT INTO public.beta_codes(code, created_by, note) VALUES (v, auth.uid(), nullif(left(trim(coalesce(p_note,'')),120),'')); n := n + 1; RETURN NEXT v;
    EXCEPTION WHEN unique_violation THEN NULL; END;
  END LOOP;
END $$;


--
-- Name: create_culture_a2e(text, text, text, text, text, text, date, integer, text, text, text[], integer, text, text, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_culture_a2e(p_kind text, p_mode text, p_title text, p_country text, p_region text, p_city text, p_start date, p_days integer, p_layer text, p_vibe text, p_types text[], p_prep integer, p_finale text, p_place text, p_repeat boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_exp uuid; v_trip uuid; v_dest text; v_end date; v_tz text; v_code text; v_age int; v_mid date; v_final timestamptz; i int;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'Sign in to the private beta first'; END IF;
 v_age:=coalesce(trip_private.age_of(auth.uid()),0);
 IF v_age<13 THEN RAISE EXCEPTION 'Players must be at least 13'; END IF;
 IF p_kind NOT IN ('explore','show','inspire') OR (p_kind='inspire' AND p_mode NOT IN ('solo','group')) OR (p_kind='explore' AND p_mode IS DISTINCT FROM 'group') OR (p_kind='show' AND p_mode NOT IN ('solo','group')) THEN RAISE EXCEPTION 'Choose a valid way to play'; END IF;
 IF p_kind='inspire' AND p_layer IS NOT NULL OR p_kind<>'inspire' AND (p_layer NOT IN ('food','music','language','traditions','history','fashion','games','everyday','mixed') OR (p_layer='mixed' AND p_kind<>'explore')) THEN RAISE EXCEPTION 'Choose a culture layer'; END IF;
 IF upper(coalesce(p_country,'')) !~ '^[A-Z]{2}$' OR length(trim(coalesce(p_title,''))) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Choose a country and a name'; END IF;
 IF p_start IS NULL OR p_start<current_date OR p_start>current_date+365 OR p_days<1 OR p_days>3650 OR p_start+p_days-1>date '9999-12-31' THEN RAISE EXCEPTION 'Check the dates'; END IF;
 IF p_kind<>'inspire' AND p_days NOT BETWEEN 2 AND 7 THEN RAISE EXCEPTION 'From Home runs for 2–7 days'; END IF;
 IF p_prep NOT BETWEEN 0 AND 10 THEN RAISE EXCEPTION 'Choose up to ten prep days'; END IF;
 IF p_kind<>'inspire' AND p_prep<>0 THEN RAISE EXCEPTION 'Preparation is for Window Seat'; END IF;
 IF p_vibe NOT IN ('family','chill','party') OR (v_age<18 AND p_vibe<>'family') OR (v_age<21 AND p_vibe='party') THEN RAISE EXCEPTION 'Pick an age-appropriate vibe'; END IF;
 IF cardinality(coalesce(p_types,'{}'))>2 OR (SELECT count(DISTINCT x) FROM unnest(coalesce(p_types,'{}')) x)<>cardinality(coalesce(p_types,'{}')) OR EXISTS (SELECT 1 FROM unnest(coalesce(p_types,'{}')) x WHERE x NOT IN ('foodie','explorer','culture','chill','photographer','night_owl','shopper')) OR ('night_owl'=ANY(coalesce(p_types,'{}')) AND v_age<21) THEN RAISE EXCEPTION 'Pick up to two age-appropriate traveler types'; END IF;
 IF p_kind='inspire' AND p_mode='group' AND p_prep>0 THEN RAISE EXCEPTION 'Prep quests are for Solo Window Seat'; END IF; IF p_mode='group' AND v_age<21 THEN RAISE EXCEPTION 'Captains must be 21 or older'; END IF;
 IF p_mode='group' AND p_kind<>'inspire' AND (p_finale NOT IN ('two_nights','finale_only') OR (p_finale='two_nights' AND p_days<4) OR length(trim(coalesce(p_place,''))) NOT BETWEEN 2 AND 120) THEN RAISE EXCEPTION 'Choose an in-person finale place and format'; END IF;
 IF p_kind='show' AND NOT p_repeat AND EXISTS (SELECT 1 FROM public.culture_layer_stamps WHERE creator_id=auth.uid() AND country=upper(p_country) AND culture_layer=p_layer) THEN RAISE EXCEPTION 'You finished this layer. Choose Do it again to replay it.'; END IF;
 IF (SELECT count(*) FROM public.culture_experiences WHERE creator_id=auth.uid() AND created_at>now()-interval '1 day')>=10 THEN RAISE EXCEPTION 'Daily limit reached'; END IF;
 SELECT coalesce(nullif(time_zone,''),'UTC') INTO v_tz FROM public.profiles WHERE id=auth.uid(); v_tz:=coalesce(v_tz,'UTC');
 v_end:=p_start+p_days-1; v_dest:=coalesce(nullif(trim(p_city),''),nullif(trim(p_region),''),upper(p_country));
 IF p_mode='group' THEN
  FOR i IN 1..15 LOOP
   BEGIN
    v_code:=public.new_trip_code();
    INSERT INTO public.trips(name,destination,start_date,end_date,home_timezone,trip_timezone,join_code,kind,season_rule,season_scoring,vibe,finale_format,finale_place,finale_at,game_start,a2e_room)
    VALUES (left(trim(p_title),100),v_dest,p_start,v_end,v_tz,v_tz,v_code,CASE WHEN p_kind='inspire' THEN 'trip' ELSE 'at_home' END,'a2c',p_kind='inspire',p_vibe,CASE WHEN p_kind='inspire' THEN NULL WHEN p_finale='two_nights' THEN 'two_nights' ELSE 'finale' END,CASE WHEN p_kind='inspire' THEN NULL ELSE trim(p_place) END,CASE WHEN p_kind='inspire' THEN NULL ELSE (v_end+time '19:00') AT TIME ZONE v_tz END,greatest(current_date,p_start-7),true) RETURNING id INTO v_trip;
    EXIT;
   EXCEPTION WHEN unique_violation THEN IF i=15 THEN RAISE; END IF;
   END;
  END LOOP;
  INSERT INTO public.trip_members(trip_id,user_id,role,status,approved_at) VALUES(v_trip,auth.uid(),'captain','approved',now());
  IF p_kind<>'inspire' THEN
   v_final:=(v_end+time '19:00') AT TIME ZONE v_tz;
   IF p_finale='two_nights' THEN v_mid:=p_start+(p_days/2)-1; INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(v_trip,1,(v_mid+time '19:00') AT TIME ZONE v_tz,auth.uid()); END IF;
   INSERT INTO public.game_nights(trip_id,week_number,starts_at,host_id) VALUES(v_trip,CASE WHEN p_finale='two_nights' THEN 2 ELSE 1 END,v_final,auth.uid());
  END IF;
 END IF;
 INSERT INTO public.culture_experiences(creator_id,track,trip_id,title,country,region,city,start_date,days,play_mode,vibe,traveler_types,prep_days,finale_format,a2e_kind,culture_layer,repeat_layer)
 VALUES(auth.uid(),CASE WHEN p_kind='inspire' THEN 'travel' ELSE 'home' END,v_trip,trim(p_title),upper(p_country),nullif(trim(p_region),''),nullif(trim(p_city),''),p_start,p_days,p_mode,p_vibe,CASE WHEN p_mode='solo' THEN coalesce(p_types,'{}') ELSE '{}' END,CASE WHEN p_kind='inspire' THEN p_prep ELSE NULL END,CASE WHEN p_mode='group' AND p_kind<>'inspire' THEN p_finale END,p_kind,p_layer,p_repeat) RETURNING id INTO v_exp;
 RETURN v_exp;
END $_$;


--
-- Name: create_teen_invite(uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_teen_invite(p_trip uuid, p_guardian boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE tok text := ''; bytes bytea := extensions.gen_random_bytes(10); i int; BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only the Captain can create teen invites'; END IF;
 IF NOT coalesce(p_guardian,false) THEN RAISE EXCEPTION 'Please confirm you are this player''s parent/guardian or have their parent''s permission'; END IF;
 IF (SELECT vibe FROM public.trips WHERE id=p_trip)='party' THEN RAISE EXCEPTION 'Teens can''t join Party trips. Switch the vibe to Family or Chill first.'; END IF;
 IF (SELECT count(*) FROM public.trip_invites WHERE trip_id=p_trip AND used_at IS NULL AND cancelled_at IS NULL AND expires_at > now()) >= 50 THEN RAISE EXCEPTION 'That''s 50 open invites — cancel some first'; END IF;
 FOR i IN 0..9 LOOP tok := tok || substr('ABCDEFGHJKLMNPQRSTUVWXYZ', get_byte(bytes,i) % 24 + 1, 1); END LOOP;
 INSERT INTO public.trip_invites(token,trip_id,created_by,teen,guardian_confirmed_at) VALUES (tok,p_trip,auth.uid(),true,now());
 RETURN tok; END $$;


--
-- Name: create_trip(text, text, date, date, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_trip(p_name text, p_destination text, p_start_date date, p_end_date date, p_home_timezone text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE trip_id uuid; attempt int; BEGIN 
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 
 IF coalesce(trip_private.age_of(auth.uid()),0) < 21 THEN RAISE EXCEPTION 'Captains are 21+. Ask your crew''s Captain to invite you.'; END IF; IF NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'TripJunkies is invite-only during the private beta'; END IF;
 IF length(trim(coalesce(p_name,''))) NOT BETWEEN 1 AND 100 OR length(trim(coalesce(p_destination,''))) NOT BETWEEN 1 AND 120 OR p_start_date IS NULL OR p_end_date IS NULL OR p_end_date < p_start_date OR length(trim(coalesce(p_home_timezone,''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Check your trip details'; END IF;
 FOR attempt IN 1..15 LOOP
  BEGIN
   INSERT INTO public.trips(name,destination,start_date,end_date,home_timezone,join_code) VALUES (trim(p_name),trim(p_destination),p_start_date,p_end_date,trim(p_home_timezone),public.new_trip_code()) RETURNING id INTO trip_id;
   EXIT;
  EXCEPTION WHEN unique_violation THEN IF attempt = 15 THEN RAISE; END IF;
  END;
 END LOOP;
 INSERT INTO public.trip_members(trip_id,user_id,role) VALUES(trip_id,auth.uid(),'captain');
 RETURN trip_id;
END $$;


--
-- Name: create_trip_a2c(text, text, date, date, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_trip_a2c(p_name text, p_destination text, p_start_date date, p_end_date date, p_home_timezone text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid; v_today date;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 IF coalesce(trip_private.age_of(auth.uid()),0)<21 THEN RAISE EXCEPTION 'Captains are 21+. Ask your crew''s Captain to invite you.'; END IF;
 IF NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'TripJunkies is invite-only during the private beta'; END IF;
 IF length(trim(coalesce(p_name,''))) NOT BETWEEN 1 AND 100 OR length(trim(coalesce(p_destination,''))) NOT BETWEEN 1 AND 120 OR p_start_date IS NULL OR p_end_date IS NULL OR p_end_date<p_start_date OR length(trim(coalesce(p_home_timezone,''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Check your trip details'; END IF;
 v_today:=(now() AT TIME ZONE p_home_timezone)::date;
 IF p_end_date-p_start_date NOT BETWEEN 1 AND 29 THEN RAISE EXCEPTION 'Trips can be 2 to 30 days long'; END IF; IF p_end_date<v_today OR p_start_date>v_today+365 THEN RAISE EXCEPTION 'Choose a trip that is still underway or ahead of you'; END IF;
 -- A new, already-underway Trip cannot inherit a past Pre-Flight window.
 IF p_start_date<v_today AND p_end_date-v_today>30 THEN RAISE EXCEPTION 'Trip is too long'; END IF;
 INSERT INTO public.trips(name,destination,start_date,end_date,home_timezone,join_code,season_rule)
 VALUES(trim(p_name),trim(p_destination),p_start_date,p_end_date,trim(p_home_timezone),public.new_trip_code(),'a2c') RETURNING id INTO v_id;
 INSERT INTO public.trip_members(trip_id,user_id,role) VALUES(v_id,auth.uid(),'captain');
 RETURN v_id;
END $$;


--
-- Name: create_trip_invite(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_trip_invite(p_trip uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE tok text := ''; bytes bytea := extensions.gen_random_bytes(10); i int; BEGIN
 IF NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Only trip leaders can invite'; END IF;
 IF (SELECT count(*) FROM public.trip_invites WHERE trip_id=p_trip AND used_at IS NULL AND cancelled_at IS NULL AND expires_at > now()) >= 50 THEN RAISE EXCEPTION 'That''s 50 open invites — cancel some first'; END IF;
 FOR i IN 0..9 LOOP tok := tok || substr('ABCDEFGHJKLMNPQRSTUVWXYZ', get_byte(bytes,i) % 24 + 1, 1); END LOOP;
 INSERT INTO public.trip_invites(token,trip_id,created_by) VALUES (tok,p_trip,auth.uid());
 RETURN tok; END $$;


--
-- Name: create_trip_play_mode(text, text, date, date, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_trip_play_mode(p_name text, p_destination text, p_start_date date, p_end_date date, p_home_timezone text, p_mode text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_id uuid;
BEGIN
 IF p_mode NOT IN ('solo','online','offline') THEN RAISE EXCEPTION 'Choose who is playing'; END IF;
 v_id:=trip_private.create_trip_a2c(p_name,p_destination,p_start_date,p_end_date,p_home_timezone);
 UPDATE public.trips SET play_arrangement=p_mode, join_code_enabled=(p_mode='online'), game_start=CASE WHEN p_start_date <= (now() AT TIME ZONE p_home_timezone)::date+1 THEN NULL ELSE greatest((now() AT TIME ZONE p_home_timezone)::date,p_start_date-10) END, game_plan=CASE WHEN p_start_date <= (now() AT TIME ZONE p_home_timezone)::date+1 THEN 'date_driven' ELSE NULL END WHERE id=v_id AND season_rule='a2c' AND is_sandbox=false;
 RETURN v_id;
END $$;


--
-- Name: create_trip_play_mode_v2(text, text, date, date, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_trip_play_mode_v2(p_name text, p_destination text, p_start_date date, p_end_date date, p_home_timezone text, p_mode text, p_country text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_id uuid; v_exp uuid; v_days integer;
BEGIN
 IF p_mode='solo' AND coalesce(p_country,'') !~ '^[A-Z]{2}$' THEN RAISE EXCEPTION 'Choose a destination country'; END IF;
 v_id:=trip_private.create_trip_play_mode(p_name,p_destination,p_start_date,p_end_date,p_home_timezone,p_mode);
 IF p_mode='solo' THEN
  v_days:=p_end_date-p_start_date+1;
  INSERT INTO public.culture_experiences(creator_id,track,title,country,start_date,days,play_mode,vibe,traveler_types,prep_days,a2e_kind)
  VALUES(auth.uid(),'travel',p_name,upper(p_country),p_start_date,v_days,'solo','chill','{}',0,'inspire') RETURNING id INTO v_exp;
  UPDATE public.trips SET solo_experience_id=v_exp WHERE id=v_id AND play_arrangement='solo' AND season_rule='a2c' AND is_sandbox=false AND EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=v_id AND user_id=auth.uid() AND role='captain');
 END IF;
 RETURN v_id;
END $_$;


--
-- Name: create_trip_play_mode_v2(text, text, date, date, text, text, text, text[]); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_trip_play_mode_v2(p_name text, p_destination text, p_start_date date, p_end_date date, p_home_timezone text, p_mode text, p_country text, p_types text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_id uuid; v_exp uuid; v_days integer;
BEGIN
 IF p_mode='solo' AND coalesce(p_country,'') !~ '^[A-Z]{2}$' THEN RAISE EXCEPTION 'Choose a destination country'; END IF;
 IF p_mode='solo' AND (coalesce(array_length(p_types,1),0)>2 OR EXISTS (SELECT 1 FROM unnest(p_types) t WHERE t NOT IN ('foodie','explorer','chill','culture','photographer','shopper','night_owl')) OR ('night_owl'=ANY(p_types) AND trip_private.age_of(auth.uid())<21)) THEN RAISE EXCEPTION 'Choose up to two age-appropriate traveler types'; END IF;
 v_id:=trip_private.create_trip_play_mode(p_name,p_destination,p_start_date,p_end_date,p_home_timezone,p_mode);
 IF p_mode='solo' THEN
  v_days:=p_end_date-p_start_date+1;
  INSERT INTO public.culture_experiences(creator_id,track,title,country,start_date,days,play_mode,vibe,traveler_types,prep_days,a2e_kind)
  VALUES(auth.uid(),'travel',trim(p_name),upper(p_country),p_start_date,v_days,'solo','chill',coalesce(p_types,'{}'::text[]),0,'inspire') RETURNING id INTO v_exp;
  UPDATE public.trips SET solo_experience_id=v_exp WHERE id=v_id AND play_arrangement='solo' AND season_rule='a2c' AND is_sandbox=false AND EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=v_id AND user_id=auth.uid() AND role='captain');
 END IF;
 RETURN v_id;
END $_$;


--
-- Name: create_window_play_mode(text, text, text, text, text, date, integer, text, text[], integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.create_window_play_mode(p_mode text, p_title text, p_country text, p_region text, p_city text, p_start date, p_days integer, p_vibe text, p_types text[], p_prep integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_exp uuid; v_trip uuid;
BEGIN
 IF p_mode NOT IN ('solo','group','offline') THEN RAISE EXCEPTION 'Choose who is playing'; END IF;
 v_exp:=trip_private.create_culture_a2e('inspire',CASE WHEN p_mode='offline' THEN 'group' ELSE p_mode END,p_title,p_country,p_region,p_city,p_start,p_days,NULL,p_vibe,p_types,p_prep,NULL,NULL,false);
 IF p_mode<>'solo' THEN
  SELECT trip_id INTO v_trip FROM public.culture_experiences WHERE id=v_exp AND creator_id=auth.uid() AND a2e_kind='inspire';
  IF v_trip IS NULL THEN RAISE EXCEPTION 'Could not create your room'; END IF;
  UPDATE public.trips SET play_arrangement=CASE WHEN p_mode='offline' THEN 'offline' ELSE 'online' END, join_code_enabled=(p_mode='group'), game_start=CASE WHEN p_start <= (now() AT TIME ZONE home_timezone)::date+1 THEN NULL ELSE greatest((now() AT TIME ZONE home_timezone)::date,p_start-10) END, game_plan=CASE WHEN p_start <= (now() AT TIME ZONE home_timezone)::date+1 THEN 'date_driven' ELSE NULL END WHERE id=v_trip AND season_rule='a2c' AND a2e_room=true AND is_sandbox=false;
 END IF;
 RETURN v_exp;
END $$;


--
-- Name: credit_cost(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.credit_cost(p_action text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ SELECT CASE p_action WHEN 'custom_game' THEN 3 WHEN 'regen_set' THEN 5 WHEN 'dest_activities' THEN 3 WHEN 'team_challenges' THEN 3 WHEN 'athome_pack' THEN 5 WHEN 'itinerary_extra' THEN 2 WHEN 'inspiration_guide' THEN 2 WHEN 'mission_topup' THEN 2 ELSE NULL END $$;


--
-- Name: credit_status(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.credit_status(p_trip uuid) RETURNS TABLE(included integer, purchased integer, used integer, remaining integer, itinerary_today integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first.'; END IF;
 included := coalesce(trip_private.credits_included(p_trip),0);
 SELECT coalesce(sum(credits),0)::int INTO purchased FROM public.ai_credit_purchases WHERE trip_id=p_trip;
 SELECT coalesce(sum(credits),0)::int INTO used FROM public.ai_usage WHERE trip_id=p_trip;
 SELECT count(*)::int INTO itinerary_today FROM public.ai_usage WHERE trip_id=p_trip AND kind='itinerary' AND created_at >= date_trunc('day', now());
 remaining := greatest(0, included + purchased - used); RETURN NEXT;
END $$;


--
-- Name: credits_included(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.credits_included(p_trip uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT CASE WHEN t.level='preview' THEN CASE WHEN trip_private.feature_on(p_trip,'ai_extras') THEN (SELECT ai_credits FROM trip_private.preview_settings) ELSE 0 END
  WHEN t.unlocked_at IS NULL THEN 0 ELSE (WITH d AS (SELECT (t.end_date - t.start_date + 1) AS n) SELECT CASE WHEN n <= 5 THEN 20 WHEN n <= 10 THEN 35 WHEN n <= 15 THEN 50 ELSE 70 END FROM d) END FROM public.trips t WHERE t.id = p_trip $$;


--
-- Name: crown_due(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.crown_due() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; n integer := 0;
BEGIN
 FOR r IN SELECT s.trip_id, s.season FROM public.season_settings s
   WHERE NOT EXISTS (SELECT 1 FROM public.season_champions c WHERE c.trip_id=s.trip_id AND c.season=s.season)
     AND trip_private.effective_crowning(s.trip_id, s.season) <= now()
 LOOP
   BEGIN
     PERFORM trip_private.crown_season(r.trip_id, r.season); n := n + 1;
   EXCEPTION WHEN others THEN RAISE WARNING 'crown_due % %: %', r.trip_id, r.season, SQLERRM;
   END;
 END LOOP;
 RETURN n;
END $$;


--
-- Name: crown_now(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.crown_now(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_week integer := trip_private.takeoff_week(p_trip); BEGIN
IF v_week IS NULL OR NOT (trip_private.can_run_turns(p_trip, v_week) OR trip_private.lab_bypass(p_trip)) THEN RAISE EXCEPTION 'Only the host or a trip leader can crown the champion'; END IF;
IF NOT trip_private.lab_bypass(p_trip) AND (SELECT starts_at FROM public.game_nights WHERE trip_id=p_trip AND week_number=v_week) > now() + interval '30 minutes' THEN RAISE EXCEPTION 'The crowning happens on Takeoff Night'; END IF;
UPDATE public.season_settings SET crowning_at=now() WHERE trip_id=p_trip AND season='game' AND crowning_mode='takeoff' AND crowning_at IS NULL;
END $$;


--
-- Name: crown_season(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.crown_season(p_trip uuid, p_season text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE st public.season_settings; v_at timestamptz;
BEGIN
 IF NOT coalesce((SELECT season_scoring FROM public.trips WHERE id=p_trip),true) THEN RETURN; END IF;
 SELECT * INTO st FROM public.season_settings WHERE trip_id=p_trip AND season=p_season; IF NOT FOUND THEN RETURN; END IF;
 v_at:=trip_private.effective_crowning(p_trip,p_season); IF v_at IS NULL OR v_at>now() THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('crown'||p_trip::text||p_season));
 IF EXISTS(SELECT 1 FROM public.season_champions WHERE trip_id=p_trip AND season=p_season) THEN RETURN; END IF;
 PERFORM set_config('trip_private.crowning','on',true);
 IF p_season='trip' THEN
   INSERT INTO public.season_champions(trip_id,season,user_id,score,stamps)
   WITH r AS (SELECT user_id,stamps,score FROM trip_private.trip_season_score(p_trip))
   SELECT p_trip,'trip',r.user_id,r.score,r.stamps FROM r WHERE r.stamps>0 AND (SELECT count(*) FROM r o WHERE (o.score,o.stamps)>(r.score,r.stamps))<st.winners;
 ELSE
   INSERT INTO public.season_champions(trip_id,season,user_id,score,stamps,tie_ids)
   WITH r AS (SELECT * FROM trip_private.game_board(p_trip) WHERE stamps>0),
   k AS (SELECT r.*,(SELECT count(*) FROM r o WHERE (o.score,o.attended)>(r.score,r.attended)) ahead,(SELECT array_agg(o.user_id ORDER BY o.user_id) FROM r o WHERE o.score=r.score AND o.attended=r.attended) grp,row_number() OVER (ORDER BY r.score DESC,r.attended DESC,random()) rn FROM r)
   SELECT p_trip,'game',k.user_id,k.score,k.stamps,CASE WHEN cardinality(k.grp)>1 AND k.ahead+cardinality(k.grp)>st.winners THEN k.grp END FROM k WHERE k.rn<=st.winners;
 END IF;
 PERFORM set_config('trip_private.crowning','',true);
END $$;


--
-- Name: culture_a2e_action(uuid, text, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_a2e_action(p_exp uuid, p_action text, p_cards jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; d jsonb; n int; v_saved int:=0;
BEGIN
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
 IF NOT FOUND OR e.creator_id IS DISTINCT FROM auth.uid() OR e.a2e_kind IS NULL THEN RAISE EXCEPTION 'Not your new experience'; END IF;
 IF p_action='save_days' THEN
  IF e.started_at IS NOT NULL THEN RAISE EXCEPTION 'Already started'; END IF;
  IF jsonb_typeof(p_cards)<>'array' OR jsonb_array_length(p_cards)>31 THEN RAISE EXCEPTION 'Save up to 31 days at a time'; END IF;
  FOR d IN SELECT * FROM jsonb_array_elements(p_cards) LOOP
   n:=(d->>'day_number')::int;
   IF n NOT BETWEEN 1 AND e.days OR length(trim(coalesce(d->>'title',''))) NOT BETWEEN 1 AND 120 OR length(trim(coalesce(d->>'what_to_do',''))) NOT BETWEEN 1 AND 600 THEN RAISE EXCEPTION 'Check the day card'; END IF;
   INSERT INTO public.culture_exp_days(experience_id,day_number,title,what_to_do,backstory,keywords,points,source)
   VALUES(e.id,n,trim(d->>'title'),trim(d->>'what_to_do'),left(coalesce(d->>'backstory',''),600),ARRAY(SELECT left(x,60) FROM jsonb_array_elements_text(coalesce(d->'keywords','[]'::jsonb)) x LIMIT 4),greatest(0,least(50,coalesce((d->>'points')::int,10))),CASE WHEN d->>'source' IN ('pool','manual','ai') THEN d->>'source' ELSE 'pool' END)
   ON CONFLICT (experience_id,day_number) DO UPDATE SET title=excluded.title,what_to_do=excluded.what_to_do,backstory=excluded.backstory,keywords=excluded.keywords,points=excluded.points,source=excluded.source;
   v_saved:=v_saved+1;
  END LOOP;
  RETURN jsonb_build_object('saved',v_saved);
 ELSIF p_action='finish' THEN
  IF e.finished_at IS NOT NULL THEN RETURN '{}'::jsonb; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.culture_exp_days WHERE experience_id=p_exp AND done_at IS NOT NULL) THEN RAISE EXCEPTION 'Do at least one day first'; END IF;
  UPDATE public.culture_experiences SET finished_at=now(),updated_at=now() WHERE id=p_exp AND creator_id=auth.uid() AND finished_at IS NULL;
  IF e.a2e_kind='show' AND NOT EXISTS(SELECT 1 FROM public.culture_layer_stamps WHERE creator_id=auth.uid() AND country=e.country AND culture_layer=e.culture_layer) THEN
   INSERT INTO public.culture_layer_stamps(experience_id,creator_id,country,culture_layer) VALUES(e.id,auth.uid(),e.country,e.culture_layer) ON CONFLICT DO NOTHING;
  END IF;
  RETURN '{}'::jsonb;
 END IF;
 RAISE EXCEPTION 'Unknown action';
END $$;


--
-- Name: culture_a2e_signup_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_a2e_signup_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.a2e_kind IS NOT NULL AND NEW.a2e_kind='explore' AND NEW.play_mode<>'group' THEN RAISE EXCEPTION 'Explore a Culture is played with others'; END IF; RETURN NEW; END $$;


--
-- Name: culture_a2e_start_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_a2e_start_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN IF NEW.a2e_kind IS NOT NULL AND NEW.started_at IS NOT NULL AND OLD.started_at IS NULL AND (SELECT count(*) FROM public.culture_exp_days WHERE experience_id=NEW.id)<NEW.days THEN RAISE EXCEPTION 'Plan every day before starting'; END IF; RETURN NEW; END $$;


--
-- Name: culture_action(text, uuid, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_action(p_action text, p_exp uuid, p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE uid uuid := auth.uid(); e public.culture_experiences; d jsonb; n int; v_id uuid; v_day public.culture_exp_days; v_photos text[]; v_with uuid[];
BEGIN
  IF uid IS NULL OR NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'Sign in first'; END IF;
  IF p_action='create' THEN
    IF (SELECT count(*) FROM public.culture_experiences WHERE creator_id=uid AND created_at > now()-interval '1 day') >= 10 THEN RAISE EXCEPTION 'Daily limit reached'; END IF;
    IF p->>'track' NOT IN ('home','travel') THEN RAISE EXCEPTION 'Pick a track'; END IF;
    IF coalesce(p->>'country','')='' THEN RAISE EXCEPTION 'Pick a place'; END IF;
    IF nullif(p->>'trip_id','') IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=(p->>'trip_id')::uuid AND user_id=uid AND status='approved') THEN RAISE EXCEPTION 'Join this squad first'; END IF;
    INSERT INTO public.culture_experiences(creator_id,track,trip_id,title,country,region,city,start_date,days)
    VALUES (uid, p->>'track', nullif(p->>'trip_id','')::uuid, left(trim(p->>'title'),120), upper(p->>'country'), nullif(left(p->>'region',80),''), nullif(left(p->>'city',80),''), coalesce(nullif(p->>'start_date','')::date, current_date), greatest(1,least(12,coalesce((p->>'days')::int,3))))
    RETURNING id INTO v_id;
    RETURN jsonb_build_object('id', v_id);
  END IF;

  SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Experience not found'; END IF; IF e.a2e_kind IS NOT NULL AND p_action IN ('visibility','like','unlike') THEN RAISE EXCEPTION 'This experience stays private to the creator and squad'; END IF;

  IF p_action='save_days' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator can edit'; END IF;
    IF e.finished_at IS NOT NULL THEN RAISE EXCEPTION 'This experience is finished'; END IF;
    IF jsonb_array_length(p->'days') > e.days THEN RAISE EXCEPTION 'Too many days'; END IF;
    FOR d IN SELECT * FROM jsonb_array_elements(p->'days') LOOP
      n := (d->>'day_number')::int;
      IF n < 1 OR n > e.days THEN RAISE EXCEPTION 'Bad day'; END IF;
      INSERT INTO public.culture_exp_days(experience_id,day_number,title,what_to_do,backstory,keywords,points,source)
      VALUES (e.id, n, left(trim(d->>'title'),120), left(coalesce(d->>'what_to_do',''),600), left(coalesce(d->>'backstory',''),600),
        (SELECT coalesce(array_agg(left(k,60)),'{}') FROM (SELECT jsonb_array_elements_text(coalesce(d->'keywords','[]'::jsonb)) k LIMIT 4) x),
        greatest(0,least(50,coalesce((d->>'points')::int,10))), CASE WHEN d->>'source' IN ('pool','ai','manual') THEN d->>'source' ELSE 'manual' END)
      ON CONFLICT (experience_id, day_number) DO UPDATE SET title=excluded.title, what_to_do=excluded.what_to_do, backstory=excluded.backstory, keywords=excluded.keywords, points=excluded.points, source=excluded.source;
    END LOOP;
    UPDATE public.culture_experiences SET updated_at=now() WHERE id=e.id;
    RETURN '{}'::jsonb;
  ELSIF p_action='start' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator'; END IF;
    UPDATE public.culture_experiences SET started_at=coalesce(started_at,now()), updated_at=now() WHERE id=e.id; RETURN '{}'::jsonb;
  ELSIF p_action='log_day' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator can log days'; END IF;
    IF e.finished_at IS NOT NULL THEN RAISE EXCEPTION 'This experience is finished'; END IF;
    SELECT coalesce(array_agg(x),'{}') INTO v_photos FROM (SELECT jsonb_array_elements_text(coalesce(p->'photos','[]'::jsonb)) x LIMIT 3) s;
    IF EXISTS (SELECT 1 FROM unnest(v_photos) ph WHERE split_part(ph,'/',1)<>e.id::text OR split_part(ph,'/',2)<>uid::text) THEN RAISE EXCEPTION 'Bad photo'; END IF;
    SELECT coalesce(array_agg(x::uuid),'{}') INTO v_with FROM (SELECT jsonb_array_elements_text(coalesce(p->'with_users','[]'::jsonb)) x LIMIT 12) s;
    IF EXISTS (SELECT 1 FROM unnest(v_with) w WHERE e.trip_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=e.trip_id AND m.user_id=w AND m.status='approved')) THEN RAISE EXCEPTION 'Only squadmates can be tagged'; END IF;
    UPDATE public.culture_exp_days SET done_at=coalesce(done_at,now()), note=nullif(left(p->>'note',500),''), photos=v_photos, with_users=v_with,
      review_stars=nullif(p->>'review_stars','')::int, review_text=nullif(left(p->>'review_text',240),''), place=nullif(left(p->>'place',120),''),
      fact=nullif(left(p->>'fact',200),''), ref_url=CASE WHEN p->>'ref_url' ~ '^https://' THEN left(p->>'ref_url',500) END
    WHERE experience_id=e.id AND day_number=(p->>'day_number')::int RETURNING * INTO v_day;
    IF NOT FOUND THEN RAISE EXCEPTION 'Day not found'; END IF;
    RETURN '{}'::jsonb;
  ELSIF p_action='confirm_day' THEN
    SELECT * INTO v_day FROM public.culture_exp_days WHERE experience_id=e.id AND day_number=(p->>'day_number')::int FOR UPDATE;
    IF NOT FOUND OR v_day.done_at IS NULL THEN RAISE EXCEPTION 'Log this day first'; END IF;
    IF NOT (e.creator_id=uid OR (e.trip_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.trip_members m WHERE m.trip_id=e.trip_id AND m.user_id=uid AND m.status='approved'))) THEN RAISE EXCEPTION 'Only you or your squad can confirm'; END IF;
    IF e.creator_id<>uid AND e.track<>'travel' THEN RAISE EXCEPTION 'Only travel cards take squad confirms'; END IF;
    UPDATE public.culture_exp_days SET confirmed_by=uid, confirmed_at=now() WHERE id=v_day.id; RETURN '{}'::jsonb;
  ELSIF p_action='set_summary' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator'; END IF;
    UPDATE public.culture_experiences SET summary=nullif(left(p->>'summary',1500),''), updated_at=now() WHERE id=e.id; RETURN '{}'::jsonb;
  ELSIF p_action='finish' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator'; END IF;
    IF NOT EXISTS (SELECT 1 FROM public.culture_exp_days WHERE experience_id=e.id AND done_at IS NOT NULL) THEN RAISE EXCEPTION 'Do at least one day first'; END IF;
    UPDATE public.culture_experiences SET finished_at=coalesce(finished_at,now()), updated_at=now() WHERE id=e.id; RETURN '{}'::jsonb;
  ELSIF p_action='visibility' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator'; END IF;
    IF p->>'visibility' NOT IN ('private','squad','public') THEN RAISE EXCEPTION 'Bad choice'; END IF;
    IF p->>'visibility'='squad' AND e.trip_id IS NULL THEN RAISE EXCEPTION 'Link a trip to share with a squad'; END IF;
    IF p->>'visibility'='public' AND coalesce(trip_private.age_of(uid),0) < 18 THEN RAISE EXCEPTION 'Sharing with all TripJunkies is for 18+'; END IF;
    UPDATE public.culture_experiences SET visibility=p->>'visibility', updated_at=now() WHERE id=e.id; RETURN '{}'::jsonb;
  ELSIF p_action IN ('like','unlike') THEN
    IF e.a2e_kind IS NOT NULL OR NOT trip_private.can_view_culture(e.id) OR e.finished_at IS NULL OR e.visibility='private' THEN RAISE EXCEPTION 'Not shared'; END IF;
    IF e.creator_id=uid THEN RAISE EXCEPTION 'No self-likes'; END IF;
    IF p_action='like' THEN INSERT INTO public.culture_exp_likes(experience_id,user_id) VALUES (e.id,uid) ON CONFLICT DO NOTHING;
    ELSE DELETE FROM public.culture_exp_likes WHERE experience_id=e.id AND user_id=uid; END IF;
    RETURN jsonb_build_object('likes',(SELECT count(*) FROM public.culture_exp_likes WHERE experience_id=e.id));
  ELSIF p_action='hide' THEN
    INSERT INTO public.culture_exp_hidden(experience_id,user_id) VALUES (e.id,uid) ON CONFLICT DO NOTHING; RETURN '{}'::jsonb;
  ELSIF p_action='report' THEN
    IF NOT trip_private.can_view_culture(e.id) THEN RAISE EXCEPTION 'Not found'; END IF;
    IF (SELECT count(*) FROM public.bug_reports WHERE user_id=uid AND kind='experience_report' AND created_at>now()-interval '1 day')>=10 THEN RAISE EXCEPTION 'Daily limit reached'; END IF;
    INSERT INTO public.bug_reports(user_id,page,description,kind) VALUES (uid,'experience:'||e.id,left(coalesce(nullif(p->>'reason',''),'Reported experience'),1000),'experience_report');
    INSERT INTO public.culture_exp_hidden(experience_id,user_id) VALUES (e.id,uid) ON CONFLICT DO NOTHING; RETURN '{}'::jsonb;
  ELSIF p_action='unlist' THEN
    IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF;
    UPDATE public.culture_experiences SET unlisted_at=CASE WHEN unlisted_at IS NULL THEN now() END WHERE id=e.id; RETURN '{}'::jsonb;
  ELSIF p_action='delete' THEN
    IF e.creator_id<>uid THEN RAISE EXCEPTION 'Only the creator'; END IF;
    DELETE FROM public.culture_experiences WHERE id=e.id; RETURN '{}'::jsonb;
  END IF;
  RAISE EXCEPTION 'Unknown action';
END $$;


--
-- Name: culture_badges(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_badges(p_user uuid) RETURNS TABLE(track text, earned_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.track, min(e.finished_at) FROM public.culture_experiences e WHERE e.creator_id=p_user AND p_user=auth.uid() AND e.finished_at IS NOT NULL GROUP BY e.track $$;


--
-- Name: culture_creator_badge(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_creator_badge(p_user uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT CASE WHEN count(DISTINCT (s.card_id,p.user_id))>=250 THEN 'Heritage Hero' WHEN count(DISTINCT (s.card_id,p.user_id))>=50 THEN 'Culture Ambassador' WHEN count(DISTINCT (s.card_id,p.user_id))>=10 THEN 'Storyteller' ELSE NULL END FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id JOIN public.cultural_inspirations c ON c.id=s.card_id WHERE auth.uid() IS NOT NULL AND p.completed_at IS NOT NULL AND (c.creator_id=p_user OR c.partner_id=p_user) AND trip_private.quest_access(c.id,auth.uid()) $$;


--
-- Name: culture_days(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_days(p_exp uuid) RETURNS SETOF public.culture_exp_days
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; r public.culture_exp_days; priv boolean;
BEGIN
  IF NOT trip_private.can_view_culture(p_exp) OR (EXISTS(SELECT 1 FROM public.culture_experiences WHERE id=p_exp AND a2e_kind IS NOT NULL) AND NOT trip_private.a2e_culture_access(p_exp)) THEN RETURN; END IF;
  SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp;
  priv := e.creator_id=auth.uid() OR trip_private.is_app_admin() OR (e.trip_id IS NOT NULL AND trip_private.is_trip_member(e.trip_id, auth.uid()));
  FOR r IN SELECT * FROM public.culture_exp_days WHERE experience_id=p_exp ORDER BY day_number LOOP
    IF NOT priv THEN r.place := CASE WHEN r.place IS NULL THEN NULL ELSE coalesce(e.city, e.region) END; r.with_users := '{}'; r.confirmed_by := CASE WHEN r.confirmed_by=e.creator_id THEN r.confirmed_by END; END IF;
    RETURN NEXT r;
  END LOOP;
END $$;


--
-- Name: culture_quest(text, uuid, uuid, text, uuid, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_quest(p_action text, p_session uuid DEFAULT NULL::uuid, p_card uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p_item uuid DEFAULT NULL::uuid, p_choice integer DEFAULT NULL::integer, p_teams integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$ DECLARE s public.culture_quest_sessions%ROWTYPE; c public.cultural_inspirations%ROWTYPE; it public.culture_quest_items%ROWTYPE; total integer; n integer; answer_count integer; payload jsonb; v_code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
IF p_action='start' THEN SELECT * INTO c FROM public.cultural_inspirations WHERE id=p_card; IF NOT FOUND OR NOT trip_private.quest_access(p_card,auth.uid()) THEN RAISE EXCEPTION 'Quest unavailable'; END IF; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=p_card; IF total<3 OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=1) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=2) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_items WHERE card_id=p_card AND round_number=3) THEN RAISE EXCEPTION 'Finish all three rounds first'; END IF; IF p_teams NOT IN (-1,0,2,3) THEN RAISE EXCEPTION 'Choose solo, friends, or two or three teams'; END IF; IF p_teams<>0 THEN FOR n IN 1..8 LOOP v_code:=upper(substr(encode(gen_random_bytes(5),'hex'),1,6)); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.culture_quest_sessions WHERE code=v_code); END LOOP; IF EXISTS(SELECT 1 FROM public.culture_quest_sessions WHERE code=v_code) THEN RAISE EXCEPTION 'Try again'; END IF; END IF; INSERT INTO public.culture_quest_sessions(card_id,host_id,code,team_count) VALUES(p_card,auth.uid(),v_code,p_teams) RETURNING * INTO s; INSERT INTO public.culture_quest_players(session_id,user_id,team_number) VALUES(s.id,auth.uid(),CASE WHEN p_teams>0 THEN 1 ELSE NULL END); p_session:=s.id;
ELSIF p_action='join' THEN IF p_code IS NULL OR upper(trim(p_code)) !~ '^[A-Z0-9]{6}$' THEN RAISE EXCEPTION 'Quest code unavailable'; END IF; SELECT * INTO s FROM public.culture_quest_sessions WHERE code=upper(trim(p_code)) AND code IS NOT NULL AND expires_at>now() AND finished_at IS NULL FOR UPDATE; IF NOT FOUND OR NOT trip_private.quest_access(s.card_id,auth.uid()) THEN RAISE EXCEPTION 'Quest code unavailable'; END IF; SELECT count(*) INTO n FROM public.culture_quest_players WHERE session_id=s.id; IF n>=6 AND NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'This quest is full'; END IF; INSERT INTO public.culture_quest_players(session_id,user_id,team_number) VALUES(s.id,auth.uid(),CASE WHEN s.team_count>0 THEN (n%s.team_count)+1 ELSE NULL END) ON CONFLICT DO NOTHING; p_session:=s.id;
END IF;
SELECT * INTO s FROM public.culture_quest_sessions WHERE id=p_session FOR UPDATE; IF NOT FOUND OR NOT trip_private.quest_access(s.card_id,auth.uid()) OR NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Quest unavailable'; END IF;
SELECT * INTO it FROM public.culture_quest_items WHERE card_id=s.card_id ORDER BY round_number,position LIMIT 1 OFFSET s.position-1; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=s.card_id;
IF p_action='answer' THEN IF s.finished_at IS NOT NULL OR s.revealed OR it.id IS DISTINCT FROM p_item OR p_choice NOT BETWEEN 0 AND 3 OR (s.team_count<>0 AND now()>s.updated_at+interval '45 seconds') THEN RAISE EXCEPTION 'This question is closed'; END IF; INSERT INTO public.culture_quest_answers(session_id,item_id,user_id,choice) VALUES(s.id,it.id,auth.uid(),p_choice) ON CONFLICT DO NOTHING;
ELSIF p_action='confirm' THEN IF s.host_id<>auth.uid() OR it.round_number<>3 OR NOT s.revealed OR p_item IS DISTINCT FROM it.id OR NOT EXISTS(SELECT 1 FROM public.culture_quest_players WHERE session_id=s.id AND user_id=p_code::uuid) THEN RAISE EXCEPTION 'Host confirmation unavailable'; END IF; UPDATE public.culture_quest_answers SET confirmed=true,awarded=awarded+5 WHERE session_id=s.id AND item_id=it.id AND user_id=p_code::uuid AND NOT confirmed; UPDATE public.culture_quest_players p SET score=(SELECT coalesce(sum(a.awarded),0) FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.user_id=p.user_id) WHERE p.session_id=s.id;
ELSIF p_action='reveal' THEN IF s.host_id<>auth.uid() OR s.finished_at IS NOT NULL OR s.revealed OR it.id IS NULL THEN RAISE EXCEPTION 'Host only'; END IF; UPDATE public.culture_quest_answers SET awarded=CASE WHEN choice=it.answer THEN 10 ELSE 0 END WHERE session_id=s.id AND item_id=it.id; UPDATE public.culture_quest_players p SET score=(SELECT coalesce(sum(a.awarded),0) FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.user_id=p.user_id) WHERE p.session_id=s.id; UPDATE public.culture_quest_sessions SET revealed=true,updated_at=now() WHERE id=s.id; s.revealed:=true;
ELSIF p_action='next' THEN IF s.host_id<>auth.uid() OR NOT s.revealed OR s.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Reveal this question first'; END IF; IF s.position>=total THEN SELECT * INTO c FROM public.cultural_inspirations WHERE id=s.card_id; UPDATE public.culture_quest_sessions SET finished_at=now(),updated_at=now() WHERE id=s.id; UPDATE public.culture_quest_players SET completed_at=now() WHERE session_id=s.id; INSERT INTO public.culture_stamps(user_id,card_id,title,points,champion) SELECT p.user_id,s.card_id, CASE WHEN c.category='Language' THEN 'Spoke ' WHEN c.category='Food' THEN 'Tasted ' ELSE 'Experienced ' END || c.title,p.score,p.score=(SELECT max(score) FROM public.culture_quest_players WHERE session_id=s.id) FROM public.culture_quest_players p CROSS JOIN public.cultural_inspirations c WHERE p.session_id=s.id AND c.id=s.card_id ON CONFLICT(user_id,card_id) DO UPDATE SET points=GREATEST(culture_stamps.points,EXCLUDED.points),champion=culture_stamps.champion OR EXCLUDED.champion,updated_at=now(); ELSE UPDATE public.culture_quest_sessions SET position=position+1,revealed=false,updated_at=now() WHERE id=s.id; END IF;
ELSIF p_action NOT IN ('state','start','join') THEN RAISE EXCEPTION 'Unknown quest action'; END IF;
SELECT * INTO s FROM public.culture_quest_sessions WHERE id=p_session; SELECT * INTO it FROM public.culture_quest_items WHERE card_id=s.card_id ORDER BY round_number,position LIMIT 1 OFFSET s.position-1; SELECT count(*) INTO total FROM public.culture_quest_items WHERE card_id=s.card_id; SELECT count(*) INTO answer_count FROM public.culture_quest_answers WHERE session_id=s.id AND item_id=it.id; SELECT jsonb_agg(jsonb_build_object('user_id',p.user_id,'score',p.score,'team',p.team_number) ORDER BY p.score DESC) INTO payload FROM public.culture_quest_players p WHERE p.session_id=s.id;
RETURN jsonb_build_object('session',s.id,'champion',CASE WHEN s.finished_at IS NOT NULL THEN EXISTS(SELECT 1 FROM public.culture_stamps st WHERE st.card_id=s.card_id AND st.user_id=auth.uid() AND st.champion) ELSE false END,'card',s.card_id,'code',s.code,'host',s.host_id,'position',s.position,'total',total,'revealed',s.revealed,'startedAt',s.updated_at,'finished',s.finished_at IS NOT NULL,'answerCount',answer_count,'players',coalesce(payload,'[]'::jsonb),'item',CASE WHEN it.id IS NULL THEN NULL ELSE jsonb_build_object('id',it.id,'round',it.round_number,'prompt',it.prompt,'options',it.options,'photo_path',it.photo_path,'challenge',it.challenge,'answer',CASE WHEN s.revealed OR s.finished_at IS NOT NULL THEN it.answer ELSE NULL END) END,'myAnswer',(SELECT a.choice FROM public.culture_quest_answers a WHERE a.session_id=s.id AND a.item_id=it.id AND a.user_id=auth.uid()),'experience',CASE WHEN s.finished_at IS NOT NULL THEN (SELECT jsonb_build_object('title',x.title,'backstory',x.backstory,'steps',x.steps,'meaning',x.meaning,'needs',x.needs) FROM public.cultural_inspirations x WHERE x.id=s.card_id) ELSE NULL END);
END $_$;


--
-- Name: culture_quest_card(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_quest_card(p_session uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT s.card_id FROM public.culture_quest_sessions s WHERE s.id=p_session AND EXISTS(SELECT 1 FROM public.culture_quest_players p WHERE p.session_id=s.id AND p.user_id=auth.uid()) AND trip_private.quest_access(s.card_id,auth.uid()) $$;


--
-- Name: culture_quest_previews(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_quest_previews() RETURNS TABLE(id uuid, trip_id uuid, creator_id uuid, partner_id uuid, category text, title text, photo_path text, quest_length text, country text, region text, city text, is_public boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT c.id,c.trip_id,c.creator_id,c.partner_id,c.category,c.title,c.photo_path,c.quest_length,c.country,c.region,c.city,trip_private.inspiration_public(c.id) FROM public.cultural_inspirations c WHERE auth.uid() IS NOT NULL AND c.hidden_at IS NULL AND c.reveal_on<=CURRENT_DATE AND c.captain_approved_at IS NOT NULL AND ((trip_private.feature_on(c.trip_id,'inspiration') AND trip_private.is_trip_member(c.trip_id,auth.uid())) OR trip_private.inspiration_public(c.id)) $$;


--
-- Name: culture_quest_stats(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_quest_stats(p_card uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT CASE WHEN auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.cultural_inspirations c WHERE c.id=p_card AND c.hidden_at IS NULL AND (c.creator_id=auth.uid() OR c.partner_id=auth.uid()) AND trip_private.is_trip_member(c.trip_id,auth.uid()) AND trip_private.feature_on(c.trip_id,'inspiration')) THEN jsonb_build_object('plays',(SELECT count(*) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card),'completed',(SELECT count(DISTINCT p.user_id) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card AND p.completed_at IS NOT NULL),'average',(SELECT coalesce(round(avg(p.score)),0) FROM public.culture_quest_players p JOIN public.culture_quest_sessions s ON s.id=p.session_id WHERE s.card_id=p_card AND p.completed_at IS NOT NULL),'reactions',(SELECT count(*) FROM public.inspiration_votes v WHERE v.card_id=p_card AND v.choice='love')) ELSE NULL END $$;


--
-- Name: culture_shared(text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_shared(p_scope text) RETURNS TABLE(id uuid, track text, title text, country text, region text, city text, days integer, summary text, visibility text, creator_name text, avatar_style text, avatar_seed text, likes integer, liked boolean, mine boolean, finished_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT e.id, e.track, e.title, e.country, e.region, e.city, e.days, e.summary, e.visibility,
    coalesce(pp.game_name,'Traveler'), coalesce(pp.avatar_style,'buddy'), coalesce(pp.avatar_seed,''),
    (SELECT count(*)::int FROM public.culture_exp_likes l WHERE l.experience_id=e.id),
    EXISTS (SELECT 1 FROM public.culture_exp_likes l WHERE l.experience_id=e.id AND l.user_id=auth.uid()),
    e.creator_id=auth.uid(), e.finished_at
  FROM public.culture_experiences e LEFT JOIN public.player_profiles pp ON pp.user_id=e.creator_id
  WHERE auth.uid() IS NOT NULL AND e.finished_at IS NOT NULL AND e.unlisted_at IS NULL AND e.visibility<>'private'
    AND e.a2e_kind IS NULL AND trip_private.can_view_culture(e.id)
    AND (p_scope='all' OR (p_scope='public' AND e.visibility='public') OR (p_scope='squad' AND e.visibility='squad'))
    AND NOT EXISTS (SELECT 1 FROM public.culture_exp_hidden h WHERE h.experience_id=e.id AND h.user_id=auth.uid())
  ORDER BY e.finished_at DESC LIMIT 100 $$;


--
-- Name: culture_showcase(text, uuid, text, jsonb); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_showcase(p_action text, p_exp uuid DEFAULT NULL::uuid, p_code text DEFAULT NULL::text, p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE e public.culture_experiences; v_code text; v_until timestamptz; v_at timestamptz; v_place text;
BEGIN
 IF auth.uid() IS NULL OR NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'Sign in to the private beta first'; END IF;
 IF p_action='join' THEN
  IF p_code !~ '^[A-Z2-9]{16}$' THEN RAISE EXCEPTION 'Showcase invitation not found'; END IF;
  SELECT * INTO e FROM public.culture_experiences WHERE showcase_code=p_code AND showcase_revoked_at IS NULL AND showcase_expires_at>now() AND a2e_kind='show' AND play_mode='solo' AND finished_at IS NOT NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'Showcase invitation expired or unavailable'; END IF;
  IF e.creator_id=auth.uid() THEN RAISE EXCEPTION 'This is your Showcase'; END IF;
  INSERT INTO public.culture_showcase_viewers(experience_id,viewer_id) VALUES(e.id,auth.uid()) ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('id',e.id);
 END IF;
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
 IF NOT FOUND OR e.a2e_kind<>'show' OR e.play_mode<>'solo' THEN RAISE EXCEPTION 'Showcase unavailable'; END IF;
 IF p_action IN ('invite','revoke','present') THEN
  IF e.creator_id IS DISTINCT FROM auth.uid() OR e.finished_at IS NULL THEN RAISE EXCEPTION 'Only the finished guide creator can do this'; END IF;
  IF p_action='invite' THEN
   v_at:=(p->>'at')::timestamptz; v_place:=btrim(coalesce(p->>'place',''));
   IF v_at IS NULL OR v_at<=now() OR v_at>now()+interval '1 year' OR length(v_place) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'Choose a future date, time and place'; END IF;
   v_code:=upper(substr(translate(encode(gen_random_bytes(12),'hex'),'01','AB'),1,16));
   v_until:=least(v_at+interval '1 day',now()+interval '30 days');
   UPDATE public.culture_experiences SET showcase_at=v_at,showcase_place=v_place,showcase_code=v_code,showcase_expires_at=v_until,showcase_revoked_at=NULL,updated_at=now() WHERE id=e.id AND creator_id=auth.uid();
   RETURN jsonb_build_object('id',e.id,'code',v_code,'at',v_at,'place',v_place);
  ELSIF p_action='revoke' THEN
   UPDATE public.culture_experiences SET showcase_revoked_at=now(),showcase_code=NULL,updated_at=now() WHERE id=e.id AND creator_id=auth.uid(); RETURN '{}'::jsonb;
  END IF;
  IF e.showcase_at IS NULL OR now()<e.showcase_at OR e.showcase_revoked_at IS NOT NULL THEN RAISE EXCEPTION 'The Showcase has not begun'; END IF;
  INSERT INTO public.culture_showcase_rewards(experience_id,creator_id) VALUES(e.id,auth.uid()) ON CONFLICT DO NOTHING;
  UPDATE public.culture_experiences SET showcase_presented_at=coalesce(showcase_presented_at,now()),updated_at=now() WHERE id=e.id AND creator_id=auth.uid(); RETURN jsonb_build_object('bonus',5);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.culture_showcase_viewers WHERE experience_id=e.id AND viewer_id=auth.uid()) THEN RAISE EXCEPTION 'Invitation required'; END IF;
 IF e.showcase_revoked_at IS NOT NULL OR e.showcase_expires_at<=now() THEN RAISE EXCEPTION 'Showcase invitation expired'; END IF;
 IF p_action='view' THEN
  RETURN jsonb_build_object('id',e.id,'title',e.title,'culture',e.country,'layer',e.culture_layer,'at',e.showcase_at,'place',e.showcase_place,'guide',(SELECT coalesce(jsonb_agg(jsonb_build_object('day',d.day_number,'title',d.title,'story',left(d.what_to_do,500)) ORDER BY d.day_number),'[]'::jsonb) FROM public.culture_exp_days d WHERE d.experience_id=e.id AND d.done_at IS NOT NULL),'reactions',(SELECT coalesce(jsonb_object_agg(reaction,n),'{}'::jsonb) FROM (SELECT reaction,count(*) n FROM public.culture_showcase_ballots WHERE experience_id=e.id GROUP BY reaction) b),'votes',(SELECT coalesce(jsonb_object_agg(vote,n),'{}'::jsonb) FROM (SELECT vote,count(*) n FROM public.culture_showcase_ballots WHERE experience_id=e.id GROUP BY vote) b),'mine',(SELECT to_jsonb(b) - 'experience_id' - 'viewer_id' FROM public.culture_showcase_ballots b WHERE b.experience_id=e.id AND b.viewer_id=auth.uid()));
 ELSIF p_action='react' THEN
  IF now()<e.showcase_at OR now()>e.showcase_at+interval '1 day' OR p->>'reaction' NOT IN ('applause','heart','star') OR p->>'vote' NOT IN ('inspiring','learned_something','would_try') THEN RAISE EXCEPTION 'Votes open on Showcase Night'; END IF;
  INSERT INTO public.culture_showcase_ballots(experience_id,viewer_id,reaction,vote) VALUES(e.id,auth.uid(),p->>'reaction',p->>'vote') ON CONFLICT DO NOTHING;
  RETURN jsonb_build_object('saved',true);
 END IF;
 RAISE EXCEPTION 'Unknown Showcase action';
END $_$;


--
-- Name: culture_switch_group(uuid, uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.culture_switch_group(p_exp uuid, p_trip uuid, p_format text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e public.culture_experiences; uid uuid := auth.uid();
BEGIN
 IF uid IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 SELECT * INTO e FROM public.culture_experiences WHERE id=p_exp FOR UPDATE;
 IF NOT FOUND OR e.creator_id IS DISTINCT FROM uid THEN RAISE EXCEPTION 'Only the person who made this experience can switch it'; END IF;
 IF coalesce(e.play_mode,'group') <> 'solo' THEN RAISE EXCEPTION 'This experience is already played with others'; END IF;
 IF e.started_at IS NOT NULL OR e.finished_at IS NOT NULL
    OR EXISTS (SELECT 1 FROM public.solo_quests q WHERE q.experience_id=p_exp AND (q.opened_at IS NOT NULL OR q.finished_at IS NOT NULL)) THEN
   RAISE EXCEPTION 'This experience has already started, so it can''t switch to playing with others';
 END IF;
 IF p_trip IS NULL OR NOT EXISTS (SELECT 1 FROM public.trips t WHERE t.id=p_trip AND NOT coalesce(t.is_sandbox,false))
    OR NOT trip_private.is_captain(p_trip) THEN
   RAISE EXCEPTION 'Pick a trip where you are the Captain';
 END IF;
 IF e.track='home' THEN
   IF p_format NOT IN ('two_nights','finale_only') THEN RAISE EXCEPTION 'Pick a finale format'; END IF;
   IF p_format='two_nights' AND e.days < 4 THEN RAISE EXCEPTION 'Two game nights need 4 or more days'; END IF;
 END IF;
 UPDATE public.culture_experiences
   SET play_mode='group', traveler_types='{}', trip_id=p_trip,
       finale_format=CASE WHEN e.track='home' THEN p_format ELSE NULL END, updated_at=now()
 WHERE id=p_exp AND creator_id=uid;
 UPDATE public.solo_quests
   SET presentation=CASE WHEN e.track='home' THEN 'at_home_finale' ELSE 'trip_meetup' END, updated_at=now()
 WHERE experience_id=p_exp AND user_id=uid AND presentation='solo_guide';
END $$;


--
-- Name: current_look(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.current_look() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT coalesce((SELECT look FROM public.app_settings WHERE id = true), '{"global":"original","pages":{}}'::jsonb) $$;


--
-- Name: current_week(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.current_week(p_trip uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT week_number FROM public.game_nights WHERE trip_id=p_trip AND starts_at <= now() + interval '12 hours' ORDER BY starts_at DESC LIMIT 1 $$;


--
-- Name: day_vote_results(uuid, date); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.day_vote_results(p_trip uuid, p_date date) RETURNS TABLE(kind text, choice_id uuid, votes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
IF p_date >= trip_private.trip_today(p_trip) THEN RETURN; END IF;
RETURN QUERY SELECT d.kind, d.choice_id, count(*)::int FROM public.day_votes d WHERE d.trip_id=p_trip AND d.day_date=p_date GROUP BY d.kind, d.choice_id; END $$;


--
-- Name: decide_room_request(uuid, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.decide_room_request(p_request uuid, p_action text, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r room_requests%ROWTYPE; t trips%ROWTYPE; v_count int;
BEGIN
  SELECT * INTO r FROM room_requests WHERE id=p_request FOR UPDATE;
  IF NOT FOUND OR NOT trip_private.is_leader(r.trip_id) THEN RAISE EXCEPTION 'Only the Captain or Co-Captain can answer requests'; END IF;
  IF p_action NOT IN ('approve','decline','block','report') THEN RAISE EXCEPTION 'Unknown action'; END IF;
  IF p_action = 'report' THEN
    INSERT INTO bug_reports(user_id, trip_id, page, description, app_version)
    VALUES (auth.uid(), r.trip_id, 'Game Rooms · join request', 'Safety report about a join request ' || r.id || coalesce(': ' || left(p_note, 500), ''), 'rooms');
    RETURN;
  END IF;
  IF r.status <> 'pending' OR r.expires_at <= now() THEN RAISE EXCEPTION 'This request is no longer waiting'; END IF;
  IF p_action = 'approve' THEN
    SELECT * INTO t FROM trips WHERE id=r.trip_id FOR UPDATE;
    IF coalesce(trip_private.age_of(r.user_id),0) < 21 THEN RAISE EXCEPTION 'This request can''t be approved'; END IF;
    SELECT count(*) INTO v_count FROM trip_members WHERE trip_id=t.id;
    IF v_count >= 30 OR (v_count >= 20 AND NOT t.big_group) THEN RAISE EXCEPTION 'This trip is full'; END IF;
    INSERT INTO trip_members(trip_id,user_id,status,approved_at) VALUES (t.id, r.user_id, 'approved', now()) ON CONFLICT DO NOTHING;
    PERFORM trip_private.apply_join_baseline(t.id, r.user_id);
    INSERT INTO beta_access(user_id, source) VALUES (r.user_id, 'invite') ON CONFLICT DO NOTHING;
    UPDATE room_requests SET status='approved', decided_by=auth.uid(), decided_at=now() WHERE id=r.id;
  ELSIF p_action = 'block' THEN
    INSERT INTO room_blocks(trip_id,user_id,blocked_by) VALUES (r.trip_id, r.user_id, auth.uid()) ON CONFLICT DO NOTHING;
    UPDATE room_requests SET status='blocked', decided_by=auth.uid(), decided_at=now() WHERE id=r.id;
  ELSE
    UPDATE room_requests SET status='declined', decided_by=auth.uid(), decided_at=now() WHERE id=r.id;
  END IF;
END $$;


