    AS $$ BEGIN
INSERT INTO public.season_settings(trip_id, season, winners, prize, crowning_label, crowning_mode) VALUES (NEW.id, 'game', 1, '', 'Takeoff Night', 'takeoff') ON CONFLICT (trip_id, season) DO NOTHING; RETURN NEW; END $$;


