    AS $$ BEGIN NEW.trip_timezone := coalesce(NEW.trip_timezone, NEW.home_timezone); RETURN NEW; END $$;


--
-- Name: delete_cost_item(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.delete_cost_item(p_item uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_trip uuid; v_title text; v_total bigint; BEGIN
  SELECT trip_id, title, total_cents INTO v_trip, v_title, v_total FROM public.cost_items WHERE id=p_item;
  IF v_trip IS NULL OR NOT trip_private.is_captain(v_trip) THEN RAISE EXCEPTION 'Only the Captain can delete trip costs'; END IF;
  DELETE FROM public.cost_items WHERE id=p_item;
  PERFORM trip_private.log_cost(v_trip, p_item, NULL, 'deleted cost', v_total, v_title);
END $$;


--
-- Name: delete_trip(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.delete_trip(p_trip uuid, p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t public.trips; n integer; BEGIN
 SELECT * INTO t FROM public.trips WHERE id=p_trip FOR UPDATE;
 IF NOT FOUND OR NOT trip_private.is_captain(p_trip) THEN RAISE EXCEPTION 'Captain only'; END IF;
 IF p_name IS DISTINCT FROM t.name AND upper(btrim(coalesce(p_name,''))) <> 'DELETE' THEN RAISE EXCEPTION 'Trip name does not match'; END IF;
 SELECT count(*) INTO n FROM public.trip_members WHERE trip_id=p_trip;
 INSERT INTO public.trip_deletion_notes(user_id,trip_name,captain_id) SELECT user_id,t.name,auth.uid() FROM public.trip_members WHERE trip_id=p_trip AND user_id<>auth.uid();
 INSERT INTO public.trip_deletion_log(trip_id,trip_name,captain_id,member_count) VALUES(p_trip,t.name,auth.uid(),n);
 DELETE FROM public.trips WHERE id=p_trip;
END $$;


