--
-- Name: trip_peek(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_peek(p_trip uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE t public.trips; v_kind text; BEGIN
 IF auth.uid() IS NULL THEN RETURN NULL; END IF;
 IF EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND status='pending') THEN v_kind := 'waiting';
 ELSIF EXISTS (SELECT 1 FROM trip_private.trip_removals WHERE trip_id=p_trip AND user_id=auth.uid()) AND NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid()) THEN v_kind := 'former';
 ELSE RETURN NULL; END IF;
 SELECT * INTO t FROM public.trips WHERE id=p_trip;
 IF t.id IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('kind', v_kind, 'trip_id', t.id, 'name', t.name, 'destination', t.destination, 'start_date', t.start_date, 'end_date', t.end_date,
  'ended', (t.ended_at IS NOT NULL OR t.end_date < current_date),
  'squad', (SELECT count(*) FROM public.trip_members WHERE trip_id=p_trip AND status='approved'),
  'nights_played', CASE WHEN v_kind='waiting' THEN 0 ELSE (SELECT count(*) FROM public.game_nights gn WHERE gn.trip_id=p_trip AND NOT gn.skipped AND gn.starts_at <= now()) END,
  'top', CASE WHEN v_kind='waiting' THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('name', x.name, 'score', x.score) ORDER BY x.score DESC) FROM (
     SELECT CASE WHEN coalesce(trip_private.age_of(b.user_id),0) >= 18 THEN coalesce(nullif(pc.game_name,''),'Player') ELSE 'Traveler' END name, b.score
     FROM trip_private.game_board(p_trip) b JOIN public.trip_members m ON m.trip_id=p_trip AND m.user_id=b.user_id AND m.status='approved'
     LEFT JOIN public.trip_player_cards pc ON pc.trip_id=p_trip AND pc.user_id=b.user_id
     WHERE t.season_scoring ORDER BY b.score DESC LIMIT 3) x), '[]'::jsonb) END);
END $$;


--
-- Name: trip_photos(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_photos(p_trip uuid) RETURNS TABLE(photo_path text, user_id uuid, source text, day_date date, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.require_feature(p_trip, 'photo_wall');
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
RETURN QUERY SELECT x.photo_path, x.user_id, x.source, x.day_date, x.created_at FROM (
  SELECT b.photo_path, b.user_id, 'bingo'::text source, b.day_date, b.created_at FROM public.bingo_marks b WHERE b.trip_id=p_trip AND b.photo_path IS NOT NULL
  UNION ALL SELECT q.photo_path, q.user_id, 'quest', q.day_date, q.created_at FROM public.quest_posts q WHERE q.trip_id=p_trip
  UNION ALL SELECT p.photo_path, p.user_id, 'challenge', p.day_date, p.created_at FROM public.photo_posts p WHERE p.trip_id=p_trip
  UNION ALL SELECT a.photo_path, a.user_id, 'airport', a.day_date, a.created_at FROM public.airport_claims a WHERE a.trip_id=p_trip AND a.photo_path IS NOT NULL) x
WHERE NOT EXISTS (SELECT 1 FROM public.photo_removed r WHERE r.trip_id=p_trip AND r.photo_path=x.photo_path) ORDER BY x.created_at DESC; END $$;


--
-- Name: trip_pot(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_pot(p_trip uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb; BEGIN
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RETURN NULL; END IF;
  SELECT jsonb_build_object(
    'total', coalesce(sum(i.total_cents),0),
    'collected', coalesce(sum((SELECT coalesce(sum(least(s.paid_cents,s.share_cents)),0) FROM public.cost_shares s WHERE s.item_id=i.id)),0),
    'has_estimates', coalesce(bool_or(i.is_estimate),false),
    'pay_note', (SELECT pay_note FROM public.trips WHERE id=p_trip),
    'categories', coalesce((SELECT jsonb_agg(jsonb_build_object('category',c.category,'total',c.t,'estimate',c.e)) FROM (
        SELECT category, sum(total_cents) t, bool_or(is_estimate) e FROM public.cost_items WHERE trip_id=p_trip GROUP BY category) c),'[]'::jsonb))
  INTO r FROM public.cost_items i WHERE i.trip_id=p_trip;
  RETURN r; END $$;


--
-- Name: trip_price(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_price(p_trip uuid, p_headcount integer) RETURNS TABLE(days integer, base_cents integer, addon_cents integer, total_cents integer, headcount integer, unlocked boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.trips; rp record; BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
SELECT * INTO t FROM public.trips WHERE id=p_trip;
SELECT * INTO rp FROM trip_private.room_pricing(p_trip);
days := t.end_date - t.start_date + 1;
headcount := greatest(1, least(30, coalesce(p_headcount, (SELECT count(*)::int FROM public.trip_members WHERE status='approved' AND trip_id=p_trip))));
IF rp.is_new THEN
  base_cents := rp.base_cents; addon_cents := rp.addon_cents;
ELSE
  base_cents := trip_private.price(CASE WHEN days <= 5 THEN 'trip_d5' WHEN days <= 10 THEN 'trip_d10' WHEN days <= 15 THEN 'trip_d15' ELSE 'trip_d16' END);
  addon_cents := CASE WHEN headcount > 20 THEN trip_private.price('legacy_big_group') ELSE 0 END;
END IF;
total_cents := base_cents + addon_cents; unlocked := t.unlocked_at IS NOT NULL;
RETURN NEXT; END $$;


--
-- Name: trip_roster(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_roster(p_trip uuid) RETURNS TABLE(user_id uuid, role text, display_name text, avatar_url text, joined_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
 IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not a member'; END IF;
 RETURN QUERY SELECT m.user_id,m.role,coalesce(c.game_name,'New traveler'),c.avatar_path,m.joined_at FROM public.trip_members m LEFT JOIN public.trip_player_cards c ON c.trip_id=m.trip_id AND c.user_id=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' ORDER BY CASE m.role WHEN 'captain' THEN 0 WHEN 'co_captain' THEN 1 ELSE 2 END,m.joined_at;
END $$;


--
-- Name: trip_season(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_season(p_trip uuid) RETURNS TABLE(user_id uuid, stamps integer, today_stamps integer, max_stamps integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_today date := trip_private.trip_today(p_trip); v_max integer; BEGIN
IF coalesce(current_setting('trip_private.crowning', true), '') <> 'on' AND NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
SELECT coalesce(sum(CASE trip_private.game_day_status(p_trip, s.d::date) WHEN 'travel' THEN 10 WHEN 'rest' THEN 0 WHEN 'off' THEN 0 ELSE 30 END),0)::int INTO v_max FROM public.trips t CROSS JOIN LATERAL generate_series(t.start_date, least(t.end_date, v_today), interval '1 day') s(d) WHERE t.id=p_trip;
RETURN QUERY
WITH raw AS (
  SELECT b.user_id u, b.day_date d, (count(*) + CASE WHEN count(*)>=9 THEN 4 ELSE 0 END)::int pts FROM public.bingo_marks b WHERE b.trip_id=p_trip GROUP BY 1,2
  UNION ALL SELECT q.user_id, q.day_date, CASE WHEN q.photo_path IS NULL THEN 1 WHEN EXISTS (SELECT 1 FROM public.quest_challenges c WHERE c.post_id=q.id AND c.decision=false) THEN 0 WHEN (SELECT count(*) FROM public.quest_thumbs th WHERE th.post_id=q.id AND th.user_id<>q.user_id)>=2 OR EXISTS (SELECT 1 FROM public.quest_challenges c WHERE c.post_id=q.id AND c.decision=true) THEN 2 ELSE 0 END FROM public.quest_posts q WHERE q.trip_id=p_trip
  UNION ALL SELECT a.user_id, a.day_date, count(*)::int FROM public.trivia_answers a WHERE a.trip_id=p_trip AND a.correct GROUP BY 1,2
  UNION ALL SELECT s.user_id, s.day_date, 3 FROM public.secret_missions s WHERE s.trip_id=p_trip AND s.revealed_at IS NOT NULL AND EXISTS (SELECT 1 FROM public.mission_votes v WHERE v.trip_id=p_trip AND v.day_date=s.day_date AND v.owner_id=s.user_id AND NOT v.caught) AND NOT EXISTS (SELECT 1 FROM public.mission_votes v WHERE v.trip_id=p_trip AND v.day_date=s.day_date AND v.owner_id=s.user_id AND v.caught)
  UNION ALL SELECT v.voter_id, v.day_date, 1 FROM public.mission_votes v WHERE v.trip_id=p_trip AND v.caught
  UNION ALL SELECT w.choice_id, w.day_date, CASE WHEN w.kind='mvp' THEN 5 ELSE 3 END FROM (SELECT dv.day_date, dv.kind, dv.choice_id, count(*) c, max(count(*)) OVER (PARTITION BY dv.day_date, dv.kind) mc FROM public.day_votes dv WHERE dv.trip_id=p_trip AND dv.day_date < v_today GROUP BY 1,2,3) w WHERE w.c=w.mc
  UNION ALL SELECT c.user_id, c.day_date, (ARRAY[2,0,1,2,1])[c.mission+1] FROM public.airport_claims c WHERE c.trip_id=p_trip AND c.mission<>1
  UNION ALL SELECT x.user_id, x.day_date, 2 FROM (SELECT c.user_id, c.day_date, abs((split_part(c.guess,':',1)::int*60+split_part(c.guess,':',2)::int) - (split_part(g.wheels_up,':',1)::int*60+split_part(g.wheels_up,':',2)::int)) diff, min(abs((split_part(c.guess,':',1)::int*60+split_part(c.guess,':',2)::int) - (split_part(g.wheels_up,':',1)::int*60+split_part(g.wheels_up,':',2)::int))) OVER (PARTITION BY c.day_date) md FROM public.airport_claims c JOIN public.trip_day_games g ON g.trip_id=c.trip_id AND g.day_date=c.day_date WHERE c.trip_id=p_trip AND c.mission=1 AND c.guess IS NOT NULL AND g.wheels_up IS NOT NULL) x WHERE x.diff=x.md
), daily AS (
  SELECT r.u, r.d, least(sum(r.pts), CASE WHEN coalesce(g.tag,dt.tag)='Travel' THEN 10 ELSE 30 END)::int pts FROM raw r LEFT JOIN public.trip_day_games g ON g.trip_id=p_trip AND g.day_date=r.d LEFT JOIN public.trip_day_tags dt ON dt.trip_id=p_trip AND dt.day_date=r.d GROUP BY r.u, r.d, g.tag, dt.tag
)
SELECT m.user_id, (coalesce(sum(dl.pts),0)+m.trip_start_stamps)::int, coalesce(sum(dl.pts) FILTER (WHERE dl.d=v_today),0)::int, v_max FROM public.trip_members m LEFT JOIN daily dl ON dl.u=m.user_id WHERE m.trip_id=p_trip AND m.status='approved' GROUP BY m.user_id, m.trip_start_stamps; END $$;


--
-- Name: trip_season_score(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_season_score(p_trip uuid) RETURNS TABLE(user_id uuid, stamps integer, today_stamps integer, max_stamps integer, score integer, carry_on integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT s.user_id,s.stamps,s.today_stamps,s.max_stamps,
  least(100,greatest(0,(CASE WHEN s.max_stamps>0 THEN round(s.stamps*100.0/s.max_stamps)::int ELSE 0 END)+coalesce(b.points,0)+coalesce(tk.pts,0)))::int,
  coalesce(b.points,0)
 FROM trip_private.trip_season(p_trip) s
 LEFT JOIN trip_private.season_quest_bonus(p_trip,'carry_on') b ON b.user_id=s.user_id
 LEFT JOIN (SELECT c.user_id, least(12,sum(c.points))::int pts FROM public.mission_claims c WHERE c.trip_id=p_trip AND c.phase='takeoff' AND c.status='released' GROUP BY c.user_id) tk ON tk.user_id=s.user_id $$;


--
-- Name: trip_season_start_at(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_season_start_at(p_trip uuid) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT coalesce(
    t.departure_confirmed_at,
    (t.start_date + 1 + time '23:59') AT TIME ZONE coalesce(t.trip_timezone, t.home_timezone)
  )
  FROM public.trips t
  WHERE t.id = p_trip
$$;


--
-- Name: trip_season_started(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_season_started(p_trip uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN
    RAISE EXCEPTION 'Join this trip first';
  END IF;
  RETURN now() >= trip_private.trip_season_start_at(p_trip);
END
$$;


--
-- Name: trip_squad_messages(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_squad_messages(p_trip uuid) RETURNS TABLE(user_id uuid, message text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
  IF NOT public.is_trip_member(p_trip, auth.uid()) THEN RETURN; END IF;
  RETURN QUERY SELECT f.user_id, f.squad_message FROM public.trip_feedback f WHERE f.trip_id=p_trip AND f.squad_message IS NOT NULL ORDER BY f.created_at; END $$;


--
-- Name: trip_today(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_today(p_trip uuid) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 SELECT (now() AT TIME ZONE coalesce(trip_timezone, home_timezone))::date FROM public.trips WHERE id=p_trip $$;


--
-- Name: trip_totals(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trip_totals(p_trip uuid) RETURNS TABLE(user_id uuid, game_stamps integer, trip_stamps integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
WITH v AS (SELECT coalesce((SELECT here_stamps FROM public.stamp_settings WHERE trip_id=p_trip),1) h, coalesce((SELECT win_stamps FROM public.stamp_settings WHERE trip_id=p_trip),3) w, coalesce((SELECT host_stamps FROM public.stamp_settings WHERE trip_id=p_trip),1) ho),
g AS (SELECT m.user_id, coalesce(sum(CASE WHEN s.here THEN v.h + CASE WHEN n.host_id=m.user_id THEN v.ho ELSE 0 END ELSE 0 END + CASE WHEN s.won THEN v.w ELSE 0 END),0)::int st
  FROM public.trip_members m CROSS JOIN v LEFT JOIN public.game_nights n ON n.trip_id=m.trip_id AND n.starts_at<=now() LEFT JOIN public.game_scores s ON s.trip_id=m.trip_id AND s.week_number=n.week_number AND s.user_id=m.user_id WHERE m.trip_id=p_trip GROUP BY m.user_id)
SELECT g.user_id, g.st, coalesce((SELECT t.stamps FROM trip_private.trip_season(p_trip) t WHERE t.user_id=g.user_id),0)::int FROM g $$;


--
-- Name: trips_minor_guard(); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.trips_minor_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
 IF NEW.has_minors AND NEW.vibe IS DISTINCT FROM 'family' THEN
   RAISE EXCEPTION 'MINORS_FAMILY: Trips with players under 18 use Family content only';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: undo_cost_payment(uuid, uuid, bigint, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.undo_cost_payment(p_item uuid, p_user uuid, p_amount_cents bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_trip uuid; s public.cost_shares; v bigint; BEGIN
  SELECT trip_id INTO v_trip FROM public.cost_items WHERE id=p_item;
  IF v_trip IS NULL OR NOT trip_private.is_captain(v_trip) THEN RAISE EXCEPTION 'Only the Captain can undo payments'; END IF;
  IF nullif(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Add a short reason'; END IF;
  SELECT * INTO s FROM public.cost_shares WHERE item_id=p_item AND user_id=p_user;
  IF NOT FOUND THEN RAISE EXCEPTION 'That player isn''t in this cost'; END IF;
  v := least(coalesce(p_amount_cents, s.paid_cents), s.paid_cents);
  IF v <= 0 THEN RAISE EXCEPTION 'There is no confirmed payment to undo'; END IF;
  UPDATE public.cost_shares SET paid_cents=paid_cents - v WHERE item_id=p_item AND user_id=p_user;
  INSERT INTO public.cost_notes(trip_id,user_id,message) VALUES (v_trip, p_user,
    'Your '||to_char(v/100.0,'FM$999,999,990.00')||' payment couldn''t be confirmed — check with your Captain.');
  PERFORM trip_private.log_cost(v_trip, p_item, p_user, 'undid payment', v, left(trim(p_reason),200));
END $_$;


--
-- Name: unlock_big_group(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.unlock_big_group(p_trip uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT EXISTS(SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can unlock Big Group'; END IF;
UPDATE public.trips SET big_group=true WHERE id=p_trip; END $$;


--
-- Name: unlock_trip(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.unlock_trip(p_trip uuid, p_headcount integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Only the Captain can unlock the trip'; END IF;
-- Beta: free. A real checkout would verify payment here before flipping the flag.
UPDATE public.trips SET unlocked_at = coalesce(unlocked_at, now()), unlocked_by = coalesce(unlocked_by, auth.uid()),
  big_group = big_group OR coalesce(p_headcount,0) > 20 WHERE id=p_trip;
END $$;


--
-- Name: use_ai_quota(text, uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.use_ai_quota(p_kind text, p_trip uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE lim int; used int; uid uuid; BEGIN PERFORM trip_private.ai_gate(p_kind, p_trip, auth.uid());
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF;
 PERFORM trip_private.teen_block('AI');
 IF p_kind = 'arcade_mix' THEN RETURN trip_private.mix_ai_quota(p_trip); END IF;
 IF NOT trip_private.has_beta_access() THEN RAISE EXCEPTION 'AI ideas are for beta members only.'; END IF;
 IF p_trip IS NOT NULL AND NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first.'; END IF;
 lim := CASE p_kind WHEN 'names' THEN 10 WHEN 'itinerary' THEN 20 ELSE 0 END;
 IF p_trip IS NOT NULL AND (SELECT level FROM public.trips WHERE id=p_trip)='preview' THEN lim := LEAST(lim,(SELECT ai_daily FROM trip_private.preview_settings)); IF lim=0 THEN RAISE EXCEPTION 'COMING_SOON: AI ideas are coming soon for preview trips.'; END IF; END IF;
 IF lim = 0 OR (p_kind <> 'names' AND p_trip IS NULL) THEN RAISE EXCEPTION 'Not allowed'; END IF;
 IF p_kind = 'names' THEN SELECT count(*) INTO used FROM public.ai_usage WHERE kind='names' AND user_id=auth.uid() AND created_at >= date_trunc('day', now());
 ELSE SELECT count(*) INTO used FROM public.ai_usage WHERE kind=p_kind AND trip_id=p_trip AND created_at >= date_trunc('day', now()); END IF;
 IF used >= lim THEN
   IF p_kind = 'itinerary' THEN RETURN trip_private.spend_credits(p_trip, 'itinerary_extra'); END IF;
   RAISE EXCEPTION 'That''s today''s limit for AI ideas — try again tomorrow.';
 END IF;
 INSERT INTO public.ai_usage(user_id, trip_id, kind) VALUES (auth.uid(), p_trip, p_kind) RETURNING id INTO uid;
 RETURN uid;
END $$;


--
-- Name: use_captain_pass(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.use_captain_pass(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE n public.game_nights; used int; BEGIN
IF trip_private.captain_of(p_trip) IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the Captain can use a Captain pass'; END IF;
SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
IF NOT FOUND OR n.host_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Captain passes are for nights you host'; END IF;
IF n.skipped THEN RAISE EXCEPTION 'This night is already skipped'; END IF;
IF clock_timestamp() >= n.starts_at + interval '15 minutes' OR EXISTS (SELECT 1 FROM public.host_penalties WHERE trip_id=p_trip AND week_number=p_week) THEN RAISE EXCEPTION 'Too late to use a pass for this night'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(p_trip::text || auth.uid()::text || 'captain'));
IF EXISTS (SELECT 1 FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND kind='captain' AND ref=p_week::text) THEN RAISE EXCEPTION 'Already used'; END IF;
SELECT count(*) INTO used FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND kind='captain';
IF used >= trip_private.captain_pass_limit(p_trip) THEN RAISE EXCEPTION 'No Captain passes left this season'; END IF;
INSERT INTO public.skip_passes(trip_id,user_id,season,kind,ref) VALUES(p_trip,auth.uid(),'captain','captain',p_week::text);
END $$;


--
-- Name: use_host_pass(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.use_host_pass(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE n public.game_nights; used int; BEGIN
SELECT * INTO n FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE;
IF NOT FOUND OR n.host_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only this night''s host can use a pass for it'; END IF;
IF n.starts_at <= now() THEN RAISE EXCEPTION 'Game night already started'; END IF;
IF trip_private.captain_of(p_trip)=auth.uid() THEN RAISE EXCEPTION 'You''re the backup host — hand it off with a swap instead'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(p_trip::text || auth.uid()::text));
SELECT count(*) INTO used FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND season='game';
IF used >= trip_private.skip_limit(p_trip,'game') THEN RAISE EXCEPTION 'No skip passes left this season'; END IF;
INSERT INTO public.skip_passes(trip_id,user_id,season,kind,ref) VALUES(p_trip,auth.uid(),'game','host',p_week::text);
UPDATE public.game_nights SET host_id=trip_private.captain_of(p_trip) WHERE trip_id=p_trip AND week_number=p_week;
UPDATE public.host_swaps SET status='cancelled', updated_at=now() WHERE trip_id=p_trip AND week_number=p_week AND status='open';
END $$;


--
-- Name: use_item_alternative(uuid, date, text, integer, text, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.use_item_alternative(p_trip uuid, p_date date, p_kind text, p_index integer, p_alternative text, p_group boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_captain uuid; v_user uuid; BEGIN IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Not a member'; END IF; IF p_date NOT BETWEEN (SELECT start_date FROM public.trips WHERE id=p_trip) AND (SELECT end_date FROM public.trips WHERE id=p_trip) OR p_kind NOT IN ('bingo','quest','trivia') OR p_index NOT BETWEEN 0 AND 8 OR length(trim(p_alternative)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Invalid alternative'; END IF; SELECT user_id INTO v_captain FROM public.trip_members WHERE trip_id=p_trip AND role='captain' LIMIT 1; IF p_group AND NOT (auth.uid()=v_captain OR EXISTS(SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND host_id=auth.uid() AND starts_at::date=p_date)) THEN RAISE EXCEPTION 'Host or Captain only'; END IF; v_user:=CASE WHEN p_group THEN v_captain ELSE auth.uid() END; INSERT INTO public.trip_item_alternatives(trip_id,day_date,kind,item_index,user_id,alternative) VALUES(p_trip,p_date,p_kind,p_index,v_user,trim(p_alternative)) ON CONFLICT(trip_id,day_date,kind,item_index,user_id) DO UPDATE SET alternative=excluded.alternative; END $$;


--
-- Name: use_night_pass(uuid, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.use_night_pass(p_trip uuid, p_week integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE used int; BEGIN
IF NOT trip_private.is_trip_member(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week AND starts_at + interval '1 day' > now()) THEN RAISE EXCEPTION 'Pick an upcoming game night'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(p_trip::text || auth.uid()::text));
IF EXISTS (SELECT 1 FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND kind='night' AND ref=p_week::text) THEN RAISE EXCEPTION 'Already used'; END IF;
SELECT count(*) INTO used FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND season='game';
IF used >= trip_private.skip_limit(p_trip,'game') THEN RAISE EXCEPTION 'No skip passes left this season'; END IF;
INSERT INTO public.skip_passes(trip_id,user_id,season,kind,ref) VALUES(p_trip,auth.uid(),'game','night',p_week::text);
END $$;


--
-- Name: use_skip(uuid, text, text, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.use_skip(p_trip uuid, p_kind text, p_ref text, p_new text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE tr public.trips; s text; used int; BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
IF NOT trip_private.trip_open(p_trip) THEN RAISE EXCEPTION 'This trip has ended — it''s read-only now'; END IF;
IF p_kind NOT IN ('card','quest','mission','bingo') THEN RAISE EXCEPTION 'Unknown skip'; END IF;
SELECT * INTO tr FROM public.trips WHERE id=p_trip;
s := CASE WHEN (now() AT TIME ZONE tr.home_timezone)::date >= tr.start_date THEN 'trip' ELSE 'game' END;
IF s = 'game' AND p_kind <> 'card' THEN RAISE EXCEPTION 'That skip works during the trip'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(p_trip::text || auth.uid()::text));
SELECT count(*) INTO used FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND season=s;
IF used >= trip_private.skip_limit(p_trip, s) THEN RAISE EXCEPTION 'No skip passes left this season'; END IF;
IF EXISTS (SELECT 1 FROM public.skip_passes WHERE trip_id=p_trip AND user_id=auth.uid() AND kind=p_kind AND ref=coalesce(p_ref,'') AND p_kind <> 'card') THEN RAISE EXCEPTION 'Already skipped'; END IF;
IF p_kind = 'mission' THEN
  IF p_new IS NULL OR length(p_new) > 300 THEN RAISE EXCEPTION 'Missing new mission'; END IF;
  UPDATE public.secret_missions SET mission = p_new WHERE trip_id=p_trip AND user_id=auth.uid() AND day_date=(now() AT TIME ZONE tr.home_timezone)::date AND revealed_at IS NULL;
  IF NOT FOUND THEN RAISE EXCEPTION 'No open mission to skip'; END IF;
END IF;
INSERT INTO public.skip_passes(trip_id, user_id, season, kind, ref) VALUES (p_trip, auth.uid(), s, p_kind, CASE WHEN p_kind='card' THEN gen_random_uuid()::text ELSE coalesce(p_ref,'') END);
RETURN s; END $$;


--
-- Name: valid_photo(uuid, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.valid_photo(p_trip uuid, p_path text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$ SELECT p_path IS NULL OR (length(p_path) < 300 AND split_part(p_path,'/',1)=p_trip::text AND split_part(p_path,'/',2)=auth.uid()::text) $$;


--
-- Name: vote_mission(uuid, date, uuid, boolean); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.vote_mission(p_trip uuid, p_date date, p_owner uuid, p_caught boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN PERFORM trip_private.play_day(p_trip,p_date);
IF p_owner=auth.uid() THEN RAISE EXCEPTION 'You can''t vote on your own mission'; END IF;
IF NOT EXISTS (SELECT 1 FROM public.secret_missions WHERE trip_id=p_trip AND day_date=p_date AND user_id=p_owner AND revealed_at IS NOT NULL) THEN RAISE EXCEPTION 'That mission isn''t revealed yet'; END IF;
INSERT INTO public.mission_votes(trip_id,day_date,owner_id,voter_id,caught) VALUES (p_trip,p_date,p_owner,auth.uid(),coalesce(p_caught,false)) ON CONFLICT (trip_id,day_date,owner_id,voter_id) DO UPDATE SET caught=excluded.caught; END $$;


--
-- Name: vote_weekly_answer(uuid, integer, integer); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.vote_weekly_answer(p_trip uuid, p_week integer, p_idx integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_target uuid; v_n integer; v_members integer; v_votes integer; BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
IF (SELECT phase FROM public.weekly_questions WHERE trip_id=p_trip AND week_number=p_week FOR UPDATE) IS DISTINCT FROM 'voting' THEN RAISE EXCEPTION 'Voting is closed'; END IF;
SELECT o.user_id INTO v_target FROM trip_private.ordered_answers(p_trip,p_week) o WHERE o.idx=p_idx;
IF v_target IS NULL THEN RAISE EXCEPTION 'That answer was not found'; END IF;
IF v_target = auth.uid() THEN RAISE EXCEPTION 'You can''t vote for your own answer'; END IF;
INSERT INTO public.weekly_answer_votes(trip_id,week_number,voter_id,target_id) VALUES (p_trip,p_week,auth.uid(),v_target)
  ON CONFLICT (trip_id,week_number,voter_id) DO UPDATE SET target_id=EXCLUDED.target_id, created_at=now();
SELECT count(*) INTO v_n FROM public.weekly_answers WHERE trip_id=p_trip AND week_number=p_week;
SELECT count(*) INTO v_members FROM public.trip_members WHERE status='approved' AND trip_id=p_trip;
SELECT count(*) INTO v_votes FROM public.weekly_answer_votes WHERE trip_id=p_trip AND week_number=p_week;
IF v_n = 1 THEN v_members := v_members - 1; END IF;
IF v_votes >= v_members THEN PERFORM trip_private.qotw_finalize(p_trip,p_week); END IF; END $$;


--
-- Name: week_game_action(uuid, integer, text); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.week_game_action(p_trip uuid, p_week integer, p_action text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_old integer; v_new integer; v_used integer[]; BEGIN
IF NOT EXISTS (SELECT 1 FROM public.trip_members WHERE trip_id=p_trip AND user_id=auth.uid() AND role='captain') THEN RAISE EXCEPTION 'Captain only'; END IF;
IF p_action IN ('lock','unlock','hide','reveal') THEN
 UPDATE public.game_nights SET game_locked=CASE WHEN p_action='lock' THEN true WHEN p_action='unlock' THEN false ELSE game_locked END,game_revealed=CASE WHEN p_action='hide' THEN false WHEN p_action='reveal' THEN true ELSE game_revealed END WHERE trip_id=p_trip AND week_number=p_week AND game_number IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Pick this week''s game first'; END IF;
ELSIF p_action='reroll' THEN
 IF p_week=1 THEN RAISE EXCEPTION 'Week 1 stays Two Truths and a Trip'; END IF;
 SELECT game_number INTO v_old FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week AND starts_at>now() AND NOT game_locked FOR UPDATE;
 IF v_old IS NULL THEN RAISE EXCEPTION 'That game is locked or the night already started'; END IF;
 INSERT INTO public.trip_play_state(trip_id) VALUES(p_trip) ON CONFLICT DO NOTHING;
 SELECT used_games INTO v_used FROM public.trip_play_state WHERE trip_id=p_trip FOR UPDATE;
 SELECT g.number INTO v_new FROM public.game_catalog g WHERE g.number=ANY(ARRAY[1,8,12,13,14,15]) AND g.number<>v_old AND NOT(g.number=ANY(v_used)) ORDER BY random() LIMIT 1;
 IF v_new IS NULL THEN SELECT g.number INTO v_new FROM public.game_catalog g WHERE g.number=ANY(ARRAY[1,8,12,13,14,15]) AND g.number<>v_old AND g.number<>(SELECT game_number FROM public.game_nights WHERE trip_id=p_trip AND week_number=p_week-1) ORDER BY random() LIMIT 1; END IF;
 IF v_new IS NULL THEN RAISE EXCEPTION 'No other game available'; END IF;
 UPDATE public.game_nights SET game_number=v_new WHERE trip_id=p_trip AND week_number=p_week;
 UPDATE public.trip_play_state SET used_games=array_append(array_remove(v_used,v_old),v_new),spin_game=v_new,spin_week=p_week,spin_at=clock_timestamp() WHERE trip_id=p_trip;
ELSE RAISE EXCEPTION 'Unknown game action'; END IF;
END $$;


--
-- Name: weekly_question_status(uuid); Type: FUNCTION; Schema: trip_private; Owner: -
--

CREATE FUNCTION trip_private.weekly_question_status(p_trip uuid) RETURNS TABLE(week_number integer, prompt text, source text, drops_at timestamp with time zone, revealed_at timestamp with time zone, starts_at timestamp with time zone, answered integer, players integer, phase text, read_index integer, winner_id uuid, tie_ids uuid[], tie_spin_at timestamp with time zone, votes integer, my_vote integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ BEGIN
IF NOT trip_private.is_trip_member(p_trip, auth.uid()) THEN RAISE EXCEPTION 'Join this trip first'; END IF;
PERFORM trip_private.ensure_weekly_questions(p_trip);
RETURN QUERY SELECT q.week_number, CASE WHEN q.drops_at <= now() OR trip_private.is_leader(p_trip) THEN q.prompt ELSE NULL END, CASE WHEN trip_private.is_leader(p_trip) THEN q.source ELSE NULL END, q.drops_at, q.revealed_at, coalesce(n.starts_at, q.drops_at + trip_private.bonus_window(p_trip)),
 (SELECT count(*)::int FROM public.weekly_answers a WHERE a.trip_id=p_trip AND a.week_number=q.week_number), (SELECT count(*)::int FROM public.trip_members m WHERE m.status='approved' AND m.trip_id=p_trip),
 q.phase, q.read_index, q.winner_id, CASE WHEN q.revealed_at IS NOT NULL THEN q.tie_ids ELSE '{}'::uuid[] END, q.tie_spin_at,
 (SELECT count(*)::int FROM public.weekly_answer_votes v WHERE v.trip_id=p_trip AND v.week_number=q.week_number),
 (SELECT o.idx FROM public.weekly_answer_votes v JOIN trip_private.ordered_answers(p_trip,q.week_number) o ON o.user_id=v.target_id WHERE v.trip_id=p_trip AND v.week_number=q.week_number AND v.voter_id=auth.uid())
 FROM public.weekly_questions q LEFT JOIN public.game_nights n ON n.trip_id=q.trip_id AND n.week_number=q.week_number WHERE q.trip_id=p_trip AND (n.week_number IS NOT NULL OR q.week_number >= 1000) ORDER BY q.drops_at; END $$;


