-- Name: culture_experiences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.culture_experiences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    creator_id uuid NOT NULL,
    track text NOT NULL,
    trip_id uuid,
    title text NOT NULL,
    country text NOT NULL,
    region text,
    city text,
    start_date date DEFAULT CURRENT_DATE NOT NULL,
    days integer NOT NULL,
    visibility text DEFAULT 'private'::text NOT NULL,
    summary text,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    unlisted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    prep_days integer,
    play_mode text DEFAULT 'group'::text NOT NULL,
    traveler_types text[] DEFAULT '{}'::text[] NOT NULL,
    vibe text,
    finale_format text,
    a2e_kind text,
    culture_layer text,
    repeat_layer boolean DEFAULT false NOT NULL,
    showcase_at timestamp with time zone,
    showcase_place text,
    showcase_code text,
    showcase_expires_at timestamp with time zone,
    showcase_revoked_at timestamp with time zone,
    showcase_presented_at timestamp with time zone,
    CONSTRAINT culture_a2e_kind_check CHECK (((a2e_kind IS NULL) OR (a2e_kind = ANY (ARRAY['explore'::text, 'show'::text, 'inspire'::text])))),
    CONSTRAINT culture_a2e_layer_check CHECK (((culture_layer IS NULL) OR (culture_layer = ANY (ARRAY['food'::text, 'music'::text, 'language'::text, 'traditions'::text, 'history'::text, 'fashion'::text, 'games'::text, 'everyday'::text, 'mixed'::text])))),
    CONSTRAINT culture_a2e_mode_guard CHECK (((a2e_kind IS NULL) OR ((a2e_kind = 'explore'::text) AND (play_mode = 'group'::text) AND (culture_layer IS NOT NULL) AND (trip_id IS NOT NULL) AND ((days >= 2) AND (days <= 7))) OR ((a2e_kind = 'show'::text) AND (culture_layer IS NOT NULL) AND ((days >= 2) AND (days <= 7)) AND ((play_mode = 'solo'::text) OR (trip_id IS NOT NULL))) OR ((a2e_kind = 'inspire'::text) AND (culture_layer IS NULL) AND ((play_mode = 'solo'::text) OR (trip_id IS NOT NULL))))),
    CONSTRAINT culture_experiences_days_check CHECK ((((days >= 1) AND (days <= 12)) OR ((a2e_kind = 'inspire'::text) AND (days > 12) AND (days <= 3650)))),
    CONSTRAINT culture_experiences_finale_format_check CHECK ((finale_format = ANY (ARRAY['two_nights'::text, 'finale_only'::text]))),
    CONSTRAINT culture_experiences_play_mode_check CHECK ((play_mode = ANY (ARRAY['group'::text, 'solo'::text]))),
    CONSTRAINT culture_experiences_summary_check CHECK (((summary IS NULL) OR (char_length(summary) <= 1500))),
    CONSTRAINT culture_experiences_title_check CHECK (((char_length(title) >= 1) AND (char_length(title) <= 120))),
    CONSTRAINT culture_experiences_track_check CHECK ((track = ANY (ARRAY['home'::text, 'travel'::text]))),
    CONSTRAINT culture_experiences_vibe_check CHECK (((vibe IS NULL) OR (vibe = ANY (ARRAY['family'::text, 'chill'::text, 'party'::text])))),
    CONSTRAINT culture_experiences_visibility_check CHECK ((visibility = ANY (ARRAY['private'::text, 'squad'::text, 'public'::text]))),
    CONSTRAINT culture_showcase_details CHECK (((showcase_at IS NULL) OR ((a2e_kind = 'show'::text) AND (play_mode = 'solo'::text) AND ((length(showcase_place) >= 2) AND (length(showcase_place) <= 120)))))
);


--
-- Name: culture_layer_stamps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.culture_layer_stamps (
    experience_id uuid NOT NULL,
    creator_id uuid NOT NULL,
