--
-- Name: trip_player_cards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trip_player_cards (
    trip_id uuid NOT NULL,
    user_id uuid NOT NULL,
    real_name text NOT NULL,
    game_name text NOT NULL,
    avatar_style text DEFAULT 'street'::text NOT NULL,
    avatar_seed text DEFAULT ''::text NOT NULL,
    avatar_path text,
    hometown text,
    occupation text,
    fun_fact text,
    most_excited text,
    trip_persona text,
    next_year_goal text,
    stamp_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pronouns text,
    CONSTRAINT trip_player_cards_avatar_seed_check CHECK ((length(avatar_seed) <= 80)),
    CONSTRAINT trip_player_cards_avatar_style_check CHECK ((avatar_style = ANY (ARRAY['street'::text, 'crew'::text, 'hero'::text, 'photo'::text, 'traveler'::text]))),
    CONSTRAINT trip_player_cards_check CHECK (((avatar_path IS NULL) OR ((char_length(avatar_path) <= 250) AND ((avatar_path ~~ ((((trip_id)::text || '/'::text) || (user_id)::text) || '/%'::text)) OR (avatar_path ~~ (('account/'::text || (user_id)::text) || '/%'::text)))))),
    CONSTRAINT trip_player_cards_fun_fact_check CHECK ((length(fun_fact) <= 300)),
    CONSTRAINT trip_player_cards_game_name_check CHECK (((length(TRIM(BOTH FROM game_name)) >= 1) AND (length(TRIM(BOTH FROM game_name)) <= 40))),
    CONSTRAINT trip_player_cards_hometown_check CHECK ((length(hometown) <= 160)),
    CONSTRAINT trip_player_cards_most_excited_check CHECK ((length(most_excited) <= 300)),
    CONSTRAINT trip_player_cards_next_year_goal_check CHECK ((length(next_year_goal) <= 300)),
    CONSTRAINT trip_player_cards_occupation_check CHECK ((length(occupation) <= 160)),
    CONSTRAINT trip_player_cards_pronouns_check CHECK ((length(pronouns) <= 60)),
    CONSTRAINT trip_player_cards_real_name_check CHECK (((length(TRIM(BOTH FROM real_name)) >= 1) AND (length(TRIM(BOTH FROM real_name)) <= 100))),
    CONSTRAINT trip_player_cards_stamp_count_check CHECK ((stamp_count >= 0)),
    CONSTRAINT trip_player_cards_trip_persona_check CHECK (((trip_persona IS NULL) OR ((trip_persona = btrim(trip_persona)) AND ((char_length(btrim(trip_persona)) >= 2) AND (char_length(btrim(trip_persona)) <= 24)) AND (trip_persona !~ '\s\s'::text) AND (trip_persona ~ '[[:alpha:][:digit:]]'::text) AND (trip_persona !~* '(https?:|www\.|\.(com|net|org|app|io|co|me|gg|tv)(\W|$))'::text) AND (trip_persona !~ '@[[:alnum:]_]'::text) AND (public.normalize_game_name(trip_persona) !~ '(fuck|shit|bitch|cunt|nigg|fag|whore|slut|dick|pussy|rape|nazi|retard)'::text))))
);


