   FROM public.trip_members m
  WHERE ((m.trip_id = window_guide_items.trip_id) AND (m.user_id = auth.uid()) AND (m.role = 'captain'::text) AND (m.status = 'approved'::text)))) OR ((status = 'approved'::text) AND (EXISTS ( SELECT 1
   FROM public.trips t
  WHERE ((t.id = window_guide_items.trip_id) AND (t.guide_published_at IS NOT NULL)))) AND (EXISTS ( SELECT 1
   FROM public.trip_members m
  WHERE ((m.trip_id = window_guide_items.trip_id) AND (m.user_id = auth.uid()) AND (m.status = 'approved'::text)))))));


